programs.sol:
"""A lexical alternatives signal, especially Chinese 或 ('or').

Chinese disjunctions and possibility words dominate. A seen chat-start marker
reduces the prediction for standalone 或. Smaller signals recognize
Japanese/Romance alternatives,
'and/or', and slashes beside Han text. English 'or' is usually weak, except
in "one or" or after an opening parenthesis. Initial-token offsets and repeated
initial carriage returns/carets capture separate formatting effects.
These are surface-form rules, not a full semantic OR detector.
"""
import re
import regex

READS = ()
HAN = regex.compile(r'\p{Script=Han}')
# Spanish/Italian versus Portuguese function words disambiguate the letter o.
CHOICE_O = set(
    'el los las la del una un lo il gli dei delle che di con nel '
    'pero más y es al'.split()
)
ARTICLE_O = set(
    'os uma um do dos da das no nos na nas ao aos não seu sua '
    'com pela pelo são você'.split()
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', False, None)
    _, recent, previous, chat, repeated = carry
    first = previous == ''
    token = prefix.token_strings[-1]
    word = token.strip()
    # Non-None only while the document prefix repeats its first token.
    repeated = token if first else repeated if repeated == token else None
    chat = chat or token == '<|im_start|>'
    value = 0.0

    if word == '或':
        value = 3.45 if chat else 4.65
    elif word == '或者':
        value = 3.1
    elif word == '或是':
        value = 3.4
    elif word == '或者是':
        value = 2.2
    elif word in ('或许', '或許'):
        value = 1.7
    elif word in ('或将', '或將'):
        value = 5.0
    elif word == 'または':  # Japanese 'or'
        value = 1.0
    elif word == '/or':
        value = 1.25 if previous.strip().lower() == 'and' else 0.15
    elif token == ' ou':
        value = 0.55
    elif token in (' o', ' O'):
        words = re.findall(r'[^\W\d_]+', recent.lower())
        score = sum(w in CHOICE_O for w in words)
        score -= sum(w in ARTICLE_O for w in words)
        value = min(0.75, 0.2 + 0.18 * score) if score > 0 else -0.03
        if token == ' O':
            value *= 0.3
    elif word in ('/', '／') and HAN.search(previous):
        value = 1.2 if word == '／' else 0.55
    elif token in (' or', 'or'):
        if previous.strip().lower() == 'one':
            value = 0.35
        elif previous.rstrip().endswith('('):
            value = 0.3
        else:
            value = -0.08

    if repeated == '\r':
        value = 2.79
    elif repeated and set(repeated) == {'^'}:
        value = 3.3 if len(repeated) >= 4 else 1.35
    elif first and (token.startswith(('/*', '//')) and '\n' in token):
        value = 3.36 if token.startswith('//') else 1.4
    elif first and token.startswith('"""') and '\n' in token:
        value = 1.32
    elif first and value == 0.0 and word:
        ch = word[0]
        if ch.isdigit():
            value = 0.22
        elif HAN.search(ch):
            value = -0.23
        elif ch.isupper():
            value = -0.19 if ch.isascii() else -0.6
        elif ch.islower() and not ch.isascii():
            value = -0.23
        elif all(not c.isalnum() for c in word):
            value = 0.15

    return (doc, (recent + token)[-160:], token, chat, repeated), value

"""A coarse lexical approximation, with a special case for file-header markup.

The largest harvested response was the word in a <filename> tag.
The closing bracket has a smaller response, stronger at document starts.
Small background responses are approximated by punctuation, English
connectives, calendar months, domain suffixes and conversation delimiters.
This does not reproduce the component's many token-specific fluctuations.
"""
import calendar

READS = ()
MONTHS = frozenset(calendar.month_name[1:])
ADDITIVE = frozenset(
    "also too moreover furthermore additionally besides".split()
)
NEGATION = frozenset("no not neither nor never".split())
DELIMITERS = {
    "<think>": 0.109,
    "</think>": -0.035,
    "<|im_end|>": -0.033,
    "</tool_call>": -0.084,
    "</tool_response>": 0.051,
}


def background(token, at_start):
    word = token.strip()
    value = -0.0004

    if at_start:
        value -= 0.027
    if word.startswith("’"):
        value -= 0.046
    if word and set(word) == {"`"}:
        value -= 0.032
    if word in ("or", "either"):
        value += 0.029
    if word in ADDITIVE:
        value -= 0.045
    if word in NEGATION:
        value += 0.021
    if word in MONTHS:
        value += 0.037
    if word in (".com", ".org", ".net", ".edu", ".gov", ".io"):
        value -= 0.056
    if "\\t" in token:
        value += 0.049
    if word in ('":', "':", "->", "=>", "→"):
        value += 0.029
    if "�" in token:
        value -= 0.014
    if word in DELIMITERS:
        value = DELIMITERS[word]

    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous, closing_value = 0, "", 0.0
    else:
        _, position, previous, closing_value = carry
    token = prefix.token_strings[-1]
    value = background(token, position == 0)

    # Keep the literal token: a space-prefixed " <" placeholder is different.
    opening = previous == "<" and token == "filename"
    if opening:
        value = 1.417 if position == 1 else 1.412
    elif closing_value and token == ">":
        value = closing_value
    if position == 0 and token == "<":
        value = 0.006
    closing = (0.353 if position == 1 else 0.191) if opening else 0.0
    return (doc, position + 1, token, closing), float(value)

"""Predict mainly the word 'to', modulated by its grammatical surroundings.

Clause links and copulas strengthen it; familiar '... to' constructions
weaken it. Recent word frequencies distinguish Romance-language 'a' from
the English article. Other direction/infinitive markers get small fixed
responses. Three document-opening syntax patterns get separate spikes.
Most weak background and fine lexical variation are deliberately omitted.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency
import wordnet

READS = ()

# These constructions commonly select a following 'to'.
FIXED_TO = set('''according due owing pursuant prior next close near equal
    equivalent similar related relative relation regard respect subject
    opposed addition response up leading compared comparison'''.split())
INFINITIVE_SELECTORS = set('''need needs needed want wants wanted able unable
    going used ought supposed easy'''.split())
PRONOUNS = set('me us him her them you it myself yourself himself herself'.split())
LANGUAGES = ('en', 'es', 'pt', 'it', 'fr', 'ro')


@lru_cache(maxsize=16384)
def frequencies(word):
    return tuple(zipf_frequency(word, lang) for lang in LANGUAGES)


def foreign_a(context):
    words = re.findall(r'[^\W\d_]+', context.lower())[-20:]
    if len(words) < 3:
        return 0.0
    scores = [sum(frequencies(w)[i] for w in words) / len(words)
              for i in range(len(LANGUAGES))]
    scores[0] += 0.3  # Avoid mistaking English names for foreign prose.
    language = max(range(len(scores)), key=scores.__getitem__)
    return (0.0, 1.65, 1.25, 2.0, 1.1, 1.0)[language]


DIRECTION_VERBS = {'lead', 'relate', 'refer', 'correspond', 'belong',
                   'return', 'link', 'connect', 'talk'}


def to_value(token, context):
    word = token.strip()
    if context.endswith('\\'):
        return -1.5  # The mathematical arrow command, not the word.
    if not token.startswith(' ') and context and context[-1:].isalnum():
        return 0.85  # 'To' as part of an identifier.
    if word == 'TO':
        return 1.6
    if word == 'To':
        return 2.6 if context.strip() else 2.05
    match = re.search(r'([A-Za-z]+|[^\w\s])\s*$', context)
    previous = match.group(1).lower() if match else ''
    if previous in {'have', 'has', 'had'}:
        return 0.0  # The very frequent obligation construction 'have to'.
    if previous == 'according':
        return 0.12
    if previous == 'and':
        return 5.0
    if previous == 'or':
        return 4.3
    if previous in {'but', 'so', 'because'}:
        return 4.2
    if previous in {'then', 'while'}:
        return 3.1
    if previous in {'not', 'yet'}:
        return 3.2
    if previous in {'am', 'is', 'are', 'was', 'were', 'be', 'been', 'being'}:
        return 2.8
    if previous in {'.', '!', '?', ';', ':'}:
        return 1.7
    if previous == ',':
        return 2.9
    if previous == 'how':
        return 2.05
    if previous in {'where', 'what', 'which', 'whether', 'when', 'than'}:
        return 3.0
    if previous in {'as', 'like'}:
        return 2.0
    if previous == 'it':
        return 1.4
    if previous in PRONOUNS:
        return 1.85
    if previous in FIXED_TO:
        return 0.6
    bases = wordnet.base_forms(previous) if previous.isalpha() else ()
    if DIRECTION_VERBS.intersection(bases):
        return 0.7
    if 'seem' in bases:
        return 2.25
    if context.rstrip()[-1:].isdigit():
        return 1.15
    if previous in INFINITIVE_SELECTORS:
        return 1.2
    return 1.4


DIRECTION_WORDS = {' à': 2.0, ' zu': 1.1, ' å': 2.3, ' á': 1.3,
    ' att': 0.45, ' ad': 0.6, ' para': 0.2, ' pra': 0.6,
    ' к': 0.33, '到': 0.47, '至': 0.5,
    '-to': 1.4, '.to': 0.8, '_to': 0.7,
    ' into': 0.16, ' onto': 0.4, ' unto': 1.0,
    ' from': 0.1}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    context = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    if token == ':' and context == 'Title':
        value = 13.3  # A document-opening title header.
    elif token == ' com' and context == 'package':
        value = 6.93  # A document-opening Java package declaration.
    elif token == '<!' and not context:
        value = 9.0  # Document-opening markup declaration.
    elif token.strip().lower() == 'to':
        value = to_value(token, context)
    elif token in {' a', ' A'}:
        value = foreign_a(context)
    else:
        value = DIRECTION_WORDS.get(token, 0.0)
    return (doc, (context + token)[-200:]), value

programs.haiku:
"""Purpose / infinitive "to" detector for layers.1.mlp.down_proj:1221.

The component fires on the word "to" (and its equivalents "à", "zu") when it opens an
infinitive or purpose phrase that will be followed by a bare verb: "the aim is to ...",
"... and to ...", "To remove dent ...", "need to ...". Its size depends on the word before:

- strongest after "and", "or", "but" (coordinated infinitives, "and to improve");
- strong after "is"/"was" and after a comma (purpose: "the aim is to", "its goal, to");
- strong after a sentence-opening "To" ("To remove dent ...", a purpose clause);
- medium after aim/goal/purpose/way nouns;
- ordinary after verbs and adjectives ("need to", "able to", "want to");
- weak after nouns with prepositional "to" ("due to", "according to", "compared to");
- zero in "have to" / "has to", which is a modal, not a purpose phrase.

Every other token is 0 (the model also has weak, unexplained activity on Spanish/Italian
"a" and some tokenizer fragments, which this program leaves out). The rule reads only the
current and previous token.
"""

READS = ()

TO_WORDS = {" to", " To", " TO", "To", "-to"}
EQUIVALENTS = {" à": 1.9, " zu": 1.1}   # French and German infinitive markers
COORDINATORS = {" and", " or", " but"}
IS_WORDS = {" is", " was", " are", " were"}
PUNCT = {",", ":", ";"}
AIM_WORDS = {" aim", " goal", " purpose", " objective", " way", " approach", " order", " idea"}
PREPOSITIONAL = {" due", " according", " According", " compared", " related", " relating",
                 " similar", " prior", " respect", " regard", " close", " closer", " equal",
                 " adjacent", " leading", " lead", " leads", " led", " referred", " addition",
                 " next", " up", " given", " owing", " corresponding", " return", " returned",
                 " limited", " equivalent", " proportional", " available", " ready", " connected",
                 " attached", " response"}
MODAL = {" have", " has", " had"}
SENTENCE_START = {"", "-", ".", "“", '"'}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if tok in EQUIVALENTS:
        return None, EQUIVALENTS[tok]
    if tok not in TO_WORDS:
        return None, 0.0
    if prev in MODAL:
        value = 0.0
    elif prev in COORDINATORS:
        value = 4.9
    elif prev in IS_WORDS or prev in PUNCT:
        value = 2.9
    elif tok in {" To", "To"} and (prev.strip() in SENTENCE_START or prev.endswith("\n")):
        value = 2.7
    elif prev in AIM_WORDS:
        value = 1.7
    elif prev in PREPOSITIONAL:
        value = 0.6
    else:
        value = 1.4
    return None, value

programs.sol:
"""A negative pulse on the initial run of identical document tokens.

Opening punctuation, whitespace, grammatical words, and word shape set its
strength. Once a different token appears, the prediction is zero.
Fine lexical variation and mixed-token onset effects are not modeled.
"""
READS = ()

QUESTIONS = set('what when where why how which who whom whose'.split())
CONNECTIVES = set(
    'and or but nor yet so although because since unless until while '
    'whereas whether if than though of to from in on at by for with '
    'without about as into onto through after before over under between '
    'among during'.split()
)
DETERMINERS = set(
    'this that these those any some all each every no another other such '
    'both either neither'.split()
)
AUXILIARIES = set(
    'be am is are was were been being do does did done have has had '
    'can could shall should will would may might must'.split()
)
CODE_KEYWORDS = set(
    'import from class def public private protected static void const let '
    'var using namespace package function return export module include'.split()
)


def onset(s):
    t = s.strip()
    w = t.lower()
    spaced = s.startswith(' ')
    if s.startswith('<|'):
        return -3.6
    if not t:
        if '\u00a0' in s:
            return -13.7
        if s == ' ':
            return -0.4
        if '\t' in s:
            return -4.7
        if '\n' in s or '\r' in s:
            return -2.9 if s.count('\n') == 1 else -4.4
        return -3.8
    if t.isdigit():
        return -3.2
    if not any(c.isalnum() for c in t):
        if '$' in t or '`' in t:
            return -8.1
        if set(t) == {'#'}:
            return -6.2
        if any(c in t for c in ')]}') and any(c in t for c in ',.'):
            return -7.5
        if '\n' in s:
            return -4.1
        if set(t) <= set('([{'):
            return -1.1
        if set(t) <= set(':;=+-/'):
            return -2.0
        return -2.8
    if w in QUESTIONS:
        return -4.3 if spaced else -7.9
    if w in CONNECTIVES:
        return -4.1
    if w == 'the':
        return -3.1 if spaced else -2.1
    if w in {'a', 'an'}:
        return -3.7 if spaced else -4.8
    if w in DETERMINERS:
        return -3.9
    if w in AUXILIARIES:
        return -2.6 if spaced else -4.5
    if w in CODE_KEYWORDS:
        return -3.1 if spaced else -5.0
    if t.isascii() and t.isalpha():
        if len(t) == 1:
            return -1.8
        if t.istitle():
            return -1.6 if spaced else -2.6
        return -2.2 if spaced else -1.7
    return -1.8


def step(carry, prefix, upstream):
    token = prefix.token_ids[-1]
    first = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if first:
        opening_token, still_opening = token, True
    else:
        opening_token, still_opening = carry
        still_opening = still_opening and token == opening_token
    value = onset(prefix.token_strings[-1]) if still_opening else 0.0
    return (opening_token, still_opening), value

"""Predict the response to a document's initial, possibly repeated, token.

Most later tokens get zero. At the start, zeroes, tabs, common indentation
widths and escapes get negative pulses, as do unspaced greetings and
module-loading words.
Capitalized words get a smaller pulse, strengthened for WordNet's people
words and reversed for definite/demonstrative determiners. These are class
averages; they do not capture all the variation between individual words.
"""
import wordnet

READS = ()
GREETINGS = {'hi', 'hello', 'hey'}
MODULE_LOADING = {'import', 'from', '#include', '#import', 'require'}
DETERMINERS = {'the', 'this', 'that', 'these', 'those'}


def initial_value(s):
    if s == '0':
        return -11.145
    if s == '2':
        return -2.457
    if s == '\\t':
        return -15.232
    if s.startswith('\\'):
        return -4.724
    if s == '\t':
        return -9.066
    if s and set(s) == {' '} and len(s) in (2, 4, 8):
        return -5.162
    if s.startswith(' '):
        return 0.02
    if s.lower() in GREETINGS:
        return -7.66
    if s in MODULE_LOADING:
        return -3.274
    if s.istitle():
        if s.lower() in DETERMINERS:
            return 0.345
        if 'noun.person' in wordnet.categories(s):
            return -2.547
        return -1.374
    return -0.281


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_bytes[-1]
    if carry is None or carry[0] != doc:
        value = initial_value(prefix.token_strings[-1])
        return (doc, token, value), value
    if token == carry[1]:
        return carry, carry[2]
    return (doc, None, 0.0), 0.0

"""A lexical approximation to a multilingual definite-article response.

English and German articles respond modestly; Romance and Greek forms are
stronger. Recent word frequencies distinguish Italian 'il', Portuguese 'a',
and similar ambiguous spellings from pronouns, English, and code. Preceding
prepositions usually weaken the response; clause links often strengthen it.
Case and word boundaries also matter. English 'the' has a negative response
at a row/document opening.

A rolling byte buffer supplies context and joins split Greek characters.
Greek article-shaped word prefixes and the apostrophe in l' also respond.
This is not a grammatical parser: matching prefixes can fire before a word
is complete. Other tokens normally return zero. Document boundaries and
end-of-text markers clear the context.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = ('en', 'fr', 'es', 'it', 'pt', 'de', 'hu',
             'pl', 'ro', 'cs', 'fi', 'nl', 'vi', 'tr')
ARTICLES = {
    'fr': {'le': 5.0, 'la': 3.5, 'les': 3.7, 'l': 4.2},
    'es': {'el': 4.0, 'la': 3.4, 'los': 3.7, 'las': 2.9,
           'lo': 2.0},
    'it': {'il': 6.5, 'lo': 3.0, 'la': 4.8, 'i': 5.0,
           'gli': 4.1, 'le': 4.2, 'l': 5.0},
    'pt': {'o': 4.8, 'a': 4.0, 'os': 5.3, 'as': 5.0},
    'de': {'der': 0.85, 'die': 1.1, 'das': 1.15,
           'den': 1.15, 'dem': 0.65, 'des': 0.3},
    'hu': {'az': 1.7, 'a': 1.3},
}
CANDIDATES = set().union(*(set(d) for d in ARTICLES.values()))

@lru_cache(maxsize=20000)
def frequencies(word):
    return tuple(max(2.5, zipf_frequency(word, lang))
                 for lang in LANGUAGES)


def language(text):
    words = [w for w in re.findall(r'[^\W\d_]+', text.lower())
             if len(w) > 1][-20:]
    scores = [0.0] * len(LANGUAGES)
    for word in words:
        for i, frequency in enumerate(frequencies(word)):
            scores[i] += frequency
    return LANGUAGES[max(range(len(scores)), key=scores.__getitem__)]


# These are grammatical forms, not vocabulary-token identifiers.
GREEK_ARTICLES = {
    'ο': 6.0, 'η': 5.5, 'το': 7.5, 'οι': 4.5, 'τα': 4.5,
    'τη': 7.0, 'τον': 6.0, 'την': 6.5, 'του': 3.0,
    'της': 2.5, 'των': 3.5, 'τους': 3.2, 'τις': 4.5,
    'στο': 7.5, 'στα': 4.5, 'στη': 7.0, 'στον': 6.0,
    'στην': 6.5, 'στους': 3.2, 'στις': 4.5,
}
LOW_ENGLISH = set('of in to for at from through over across throughout'.split())
CLAUSE_LINKS = set('and but that so because then since perhaps maybe'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        raw, previous = b'', ''
    else:
        _, raw, previous = carry
    text = raw.decode('utf-8', errors='ignore')
    token = prefix.token_strings[-1]
    new_raw = (raw + prefix.token_bytes[-1])[-1600:]
    after = new_raw.decode('utf-8', errors='ignore')
    word = token.strip().lower()
    preceding = re.search(r"[^\W\d_]+$", text.lower())
    prev_word = preceding.group() if preceding else ''
    value = 0.0
    if word == 'the':
        value = 1.15
        if prev_word in LOW_ENGLISH or prev_word == 'all':
            value = 0.82
        elif prev_word in CLAUSE_LINKS or previous.strip() == ',':
            value = 1.4
        if token.strip() == 'The':
            value = 1.36
        if not text or previous == '<|endoftext|>':
            value = -1.07 if token.strip() == 'The' else -0.39
        elif not token[:1].isspace() and text[-1].isalnum():
            value = 0.1
    elif word in CANDIDATES:
        lang = language(text)
        value = ARTICLES.get(lang, {}).get(word, 0.0)
        if word == 'la' and value > 0:
            if prev_word == 'de':
                value = 0.55
            elif prev_word in {'à', 'á'}:
                value = 1.5
            elif prev_word in {'en', 'a', 'por'}:
                value = 2.0
            elif prev_word == 'par':
                value = 2.3
            elif prev_word in {'que', 'che', 'e', 'y', 'et'}:
                value += 1.4
            elif previous.strip() == ',':
                value = 4.6
        if token.strip().istitle() and value > 2:
            value += 0.4
        if word == 'l' and value > 0:
            if prev_word == 'de':
                value = 1.3
            elif prev_word in {'à', 'a'}:
                value = 2.5
            elif prev_word in {'que', 'che', 'e', 'et'}:
                value += 1.8
        if lang == 'es' and word in {'los', 'las'}:
            if prev_word == 'de':
                value = 1.0 if word == 'los' else 0.5
            elif prev_word == 'que' or previous.strip() in {',', ':'}:
                value += 2.0
        if lang == 'pt' and value > 0:
            if word == 'a':
                if prev_word == 'que':
                    value = 6.0
                elif prev_word == 'de':
                    value = 1.0
                elif prev_word.endswith(('ar', 'er', 'ir')):
                    value = 3.0
            if word == 'o':
                value = 8.0 if token.strip() == 'O' else 4.8
        if word == 'a' and prev_word in {'is', 'are', 'was', 'be', 'been'}:
            value = 0.0
        if lang == 'it' and token.strip() == 'I':
            value = 2.0
        if lang == 'it' and word == 'il' and prev_word == 'che':
            value += 1.8
        if word == 'l' and token.strip() == 'L':
            value *= 0.65
        if not token[:1].isspace() and text and text[-1].isalnum():
            value *= 0.02
    elif token in ("'", '’'):
        if re.search(r"(?:^|\W)(l|dell|all|nell|dall|sull)$", text.lower()):
            letter_prime = previous.strip() == 'L' and language(text) == 'en'
            value = 2.2 if letter_prime else 4.8
    # Greek articles often occupy several tokens; match the word so far.
    if after != text and re.search(r'[α-ωΑ-Ω]', after[-2:]):
        match = re.search(r'[^\W\d_]+$', after)
        if match and len(re.findall(r'[α-ωΑ-Ω]', text[-100:])) > 12:
            value = GREEK_ARTICLES.get(match.group().lower(), value)
    if token == '<|endoftext|>':
        new_raw = b''
    return (doc, new_raw, token), float(value)

programs.haiku:
"""Definite articles, in English and in other languages.

This component fires on a definite article itself: the word just before the noun it
introduces. It is strongest on some articles and weaker on others:

- English "the" (any capitalisation, with or without a leading space): about 1.
- German "die", "das", "der", "den", "dem" (as separate lowercase words): about 1.
- Romance articles as separate lowercase words, "la", "le", "les", "el", "los", "las",
  "il", "gli", "lo", "l" (Italian, French, Spanish): about 3.
- Portuguese "o" or "a" after "que", "para" or "e" (as in "que o homem"): about 5.
- The apostrophe of an elided article, after " l" or " dell" ("l'umidità", "dell'acqua"):
  about 5.

Everything else is 0. Each prediction depends only on the token and the token before it,
so the program keeps no state between positions.

To read it: `step` is called on each token in turn, and the value is high exactly on the
article words above. The `__main__` block runs it on a short list of tokens.
"""

READS = ()

ENGLISH = {"the"}
GERMAN = {"die", "das", "der", "den", "dem"}
ROMANCE = {"la", "le", "les", "el", "los", "las", "il", "gli", "lo", "l"}
PORTUGUESE_AFTER = {" que", " para", " e"}
APOSTROPHES = {"'", "’"}
ELIDED_ARTICLES = {" l", " dell"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    word = tok.strip().lower()
    spaced = tok[:1] == " "
    lower = tok.strip() == word
    value = 0.0
    if word in ENGLISH:
        value = 1.0
    elif spaced and lower and word in GERMAN:
        value = 1.0
    elif spaced and lower and word in ROMANCE:
        value = 3.0
    elif spaced and tok in {" o", " a"} and prev in PORTUGUESE_AFTER:
        value = 5.0
    elif tok in APOSTROPHES and prev in ELIDED_ARTICLES:
        value = 5.0
    return carry, float(value)


if __name__ == "__main__":
    demo = [" In", " October", ",", " the", " Italian", " el", " la", " luce", ",", " la", " temperatura", " e", " l", "'", "umidità"]
    for i, tok in enumerate(demo):
        _, v = step(None, type("P", (), {"token_strings": demo[: i + 1]})(), {})
        print(f"{tok!r:14} {v}")

programs.sol:
"""Universal quantification, strongest for 'everything' and 'everyone'.

Recognize universal words and a short quantified noun phrase. WordNet supplies
general noun classes; small named groups cover facets, parts, and exhaustive
modifiers. Polarity contrasts such as "at all" and "each other" are separate.
The phrase effect is weaker for 'each' and 'all' than for 'every'.  A short
byte tail joins split words and is cleared at document boundaries.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
WORDS = re.compile(r"[^\W\d_]+", re.UNICODE)
ALL_WORDS = set("all alle allen alles tutti tutto tous toutes toute todo todos "
                "todas tudo toda все всех всё".split())
EVERY_WORDS = set("every jeder jede jedes jedem jeden chaque cada ogni".split())
COMPOUNDS = set("everything everyone everybody everywhere everyday".split())
INTENSIFIERS = set("one thing single last possible conceivable imaginable".split())
NUMBERS = set("two three four five six seven eight nine ten "
              "few several couple".split())
FUNCTION = set("the a an this that these those my your his her its our their "
               "i you he she it we they and or but be is are was were have "
               "has had can will would could should must may might not".split())
SCALES = {"every": 1., "each": .4, "all": .35,
          "different": .2, "various": .2, "multiple": .2, "many": .15}
PARTITIONS = set("part piece element component member term case point step "
                 "side level segment section stage type kind sort "
                 "combination".split())
FACETS = set("aspect facet detail dimension direction respect sense".split())
LEXICAL = {'everything': 5.92,
 'everyone': 5.2,
 'everybody': 5.2,
 'everywhere': 4.92,
 'everyday': 4.06,
 'each': 0.16,
 'ever': 0.64,
 'always': 0.42}
NOUN_GAIN = {'day': 2.92,
 'facet': 5.71,
 'function': 0.09,
 'intensifier': 5.89,
 'location': 1.15,
 'noun': 0.57,
 'number': -0.16,
 'other': 0.26,
 'part': 0.79,
 'partition': 2.81,
 'person': 0.88,
 'quantity': 0.61,
 'time': 1.17}
LINK_GAIN = {
    'facet': 4.57,
    'general': 0.84,
    'number': 0.07,
    'partition': 1.9,
}

@lru_cache(maxsize=10000)
def noun_group(word):
    if word.rstrip("s") in FACETS:
        return "facet"
    if word.rstrip("s") in PARTITIONS:
        return "partition"
    if word in INTENSIFIERS:
        return "intensifier"
    if word in NUMBERS:
        return "number"
    if word == "day":
        return "day"
    if word in FUNCTION:
        return "function"
    cats = wordnet.categories(word)
    for name in ("time", "location", "person", "quantity"):
        if "noun." + name in cats:
            return name
    if wordnet.is_a(word, "part") or wordnet.is_a(word, "unit"):
        return "part"
    if "noun" in wordnet.parts_of_speech(word):
        return "noun"
    return "other"


def step(carry, prefix, upstream):
    doc, new = prefix.document_ids[-1], prefix.token_bytes[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else b""
    raw = (tail + new)[-192:]
    words = WORDS.findall(raw.decode("utf-8", "ignore").lower())
    token = new.decode("utf-8", "ignore").lower()
    word = words[-1] if words and any(c.isalpha() for c in token) else ""
    prev = words[-2] if len(words) > 1 else ""
    before = words[-3] if len(words) > 2 else ""
    value = 0.0019 + LEXICAL.get(word, 0.)

    if word in EVERY_WORDS:
        value += 1.41 if word == "every" else 0.73
        if prev in {"in", "of", "at", "for", "on", "between"}:
            value -= 0.37
        if prev in {"almost", "nearly", "not"}:
            value += 1.17
    if word in ALL_WORDS:
        value += 0.72 if word == "all" else 0.93
        if prev == "at":
            value -= 0.85
        if prev in {"it", "you", "them", "us"}:
            value += 0.74

    # A quantified phrase, allowing one exhaustive modifier before its noun.
    scale = SCALES.get(prev, 0.)
    if prev in EVERY_WORDS:
        scale = 1.
    if prev in ALL_WORDS or (before == "all" and prev == "the"):
        scale = .35
    if before in SCALES and prev in INTENSIFIERS | {"little", "individual"}:
        scale = SCALES[before]
    if scale and word:
        if word == "other":
            value += -0.34 if prev == "each" else 0.36
            if prev == "every":
                value = 0.0019 + 2.1  # alternating members: 'every other'
        elif word in {"of", "with", "in", "on", "to", "for"}:
            value += scale * 0.49
        else:
            group = noun_group(word)
            value += scale * NOUN_GAIN[group]
            if group in {"partition", "facet"}:
                if prev == "all":
                    value += 0.72
                if prev == "each":
                    value += 0.62
    if before in SCALES and word in {"of", "in", "has", "is", "that"}:
        group = noun_group(prev)
        value += SCALES[before] * LINK_GAIN.get(group, LINK_GAIN["general"])
    if prev in COMPOUNDS and word:
        if word in {"who", "what", "which", "else"}:
            value += 2.85
        elif word in {"is", "has", "was", "had", "can", "will"}:
            value += 0.92

    # Fixed grammatical contrasts and Mandarin quantifier tokens.
    if prev == "any" and word == "of":
        value += -1.85
    if prev == "no" and word == "one":
        value += 2.85
    if not word and token.isspace() and words and words[-1] == "every":
        value += -2.25
    if token in {"每", "每天", "每个", "每一", "每个人", "所有", "都", "全部"}:
        value += 1.55 if token.startswith("每") else 0.64
    return (doc, raw), float(value)

programs.haiku:
"""Universal-quantifier detector: fires on 'every'/'all' and their compounds, and on the word that completes an 'every ...' phrase."""

READS = ()
EVERY_COMPOUNDS = {"everything", "everyone", "everybody", "everywhere", "everyday"}
UNIVERSAL_WORDS = {"every": 1.4, "all": 0.7, "each": 0.2, "ever": 0.7, "always": 0.5,
                   "tutti": 1.4, "tutto": 0.8, "tous": 0.8, "toute": 1.0, "toutes": 0.8,
                   "tout": 0.6, "todos": 1.0, "todo": 0.7, "toda": 0.8, "todas": 0.8,
                   "ogni": 0.8, "cada": 0.5, "jeder": 2.0, "alle": 0.6, "alles": 1.5,
                   "всё": 0.9, "все": 0.8, "всех": 0.9, "所有": 0.7, "每": 0.6, "都": 0.7}

def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    before = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if word in EVERY_COMPOUNDS:
        value = 5.5
    elif word == "all" and before == "at":
        value = 0.0
    elif word in UNIVERSAL_WORDS:
        value = UNIVERSAL_WORDS[word]
    elif before == "every":
        value = 2.0
    elif before == "no" and word == "one":
        value = 2.5
    elif before == "any" and word == "of":
        value = -1.8
    else:
        value = 0.0
    return carry, value

"""Layer-1 MLP down-projection component 1228: a document-opening feature.

The component is silent after a document's first few tokens. Its activation is set by
the first two tokens of each document (positions restart where the document id changes):

- First token: marker tokens such as <|im_start|> push it up (+1.7); newlines and
  tabs slightly up; lowercase words up (+0.5); punctuation slightly down.
- Second token: it is clearly negative when the token starts a new word (a leading
  space), when it is non-ASCII text (CJK, Cyrillic, ...), when it follows a chat
  marker, or when it is punctuation. It is near zero when the token simply continues
  the first token's word or a run of digits.
"""

READS = ()

CHAT_START = "<|im_start|>"


def _kind(s):
    if s.startswith("<|"):
        return "marker"
    if not s.isascii():
        return "script"
    if s.strip() == "":
        return "space"
    if s.strip().isdigit():
        return "digit"
    if s.strip().isalnum():
        return "word"
    return "punct"


def step(carry, prefix, upstream):
    t = prefix.position
    doc = prefix.document_ids
    tok = prefix.token_strings[-1]
    if t == 0 or doc[-1] != doc[-2]:
        pos = 0
    else:
        pos = carry + 1
    if pos == 0:
        kind = _kind(tok)
        if kind == "marker":
            value = 1.7
        elif kind == "space":
            value = 1.0 if ("\n" in tok or "\t" in tok) else 0.0
        elif kind == "word" and tok[:1].islower():
            value = 0.5
        elif kind == "script":
            value = 0.35
        elif kind == "punct":
            value = -0.1
        else:
            value = 0.0
    elif pos == 1:
        if prefix.token_strings[-2] == CHAT_START:
            value = -1.8
        elif not tok.isascii() and tok.strip() != "":
            value = -1.8
        elif tok.startswith(" ") and tok.strip().isalpha():
            value = -1.7
        elif tok.strip().isalnum():
            value = -0.3
        else:
            value = -1.0
    else:
        value = 0.0
    return pos, float(value)

programs.sol:
"""A lexical acid detector, with weaker academic/acetyl/acute responses.

Acid words and the Chinese character 酸 receive large positive values.
The response is weaker for amino acids and fatty acids. Split spellings of
acid and academic stems are recognized using the preceding word fragment.
A small negative response marks split atheros- and Greek απ- spellings.
Byte fragments beginning 酸 are recognized before the character is complete;
that prefix is shared with other characters. Most other tokens predict zero.
"""
import re

READS = ()
ACID_UTF8 = "酸".encode("utf8")


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ""
    tail = carry[2] if carry is not None and carry[0] == doc else b""
    raw = prefix.token_bytes[-1]
    s = prefix.token_strings[-1]
    t = s.strip()
    low = t.lower()
    joined = previous + s if s and s[0].isalpha() else s
    match = re.search(r"[^\W\d_]+$", joined)
    word = match.group(0) if match else ""
    value = 0.0

    if low in ("acid", "acids", "acidic", "acidity"):
        value = {"acid": 6.8, "acids": 7.0,
                 "acidic": 5.3, "acidity": 4.0}[low]
        if low in ("acid", "acids"):
            if previous.lower() == "amino":
                value = 2.0 if low == "acid" else 2.4
            elif previous.lower() == "fatty":
                value = 4.6 if low == "acid" else 5.6
            elif t[:1].isupper():
                value = 8.7
    elif t == "酸":
        value = 6.9
    elif low.startswith("acet"):
        value = 3.5 if s[:1].isspace() else 2.4
    elif low.startswith("academic"):
        value = 2.4 + (0.5 if t[:1].isupper() else 0.0)
    elif low in ("acad", "academia") and s[:1].isspace():
        value = 2.1
    elif low == "acute":
        value = 0.8
    elif (low == "ac" and (s[:1].isspace() or t == "Ac")
          and t != "AC"):
        value = 0.4
    elif s.isalpha() and previous:
        w = word.lower()
        before = previous.lower()
        if (before in ("a", "ac")
                and w in ("aci", "acid", "acids", "acide", "acides")):
            value = 6.0 if w == "aci" else 10.0
        elif before == "ac" and low == "ido":
            value = 4.5
        elif before in ("a", "ac") and w.startswith(("acet", "acét")):
            value = 4.8
        elif (before in ("ac", "acad", "akad", "акад", "ад")
              and w.startswith(("acad", "akad", "академ", "адем"))):
            value = 4.5
        elif before == "a" and low == "theros":
            value = -2.3
        elif before == "α" and low == "π":
            value = -3.2
    # Only the split-byte spelling gets the large anticipatory response.
    if raw == ACID_UTF8[1:2] and tail.endswith(ACID_UTF8[:1]):
        value = 13.3
    elif raw == ACID_UTF8[2:] and tail == ACID_UTF8[:2]:
        value = 11.2
    return (doc, word[-24:], (tail + raw)[-2:]), value

"""Unspaced joiners: paths, hyphenated words, ranges, and elisions.

Standalone slashes and hyphens respond strongly after letters or digits,
not after whitespace. Path context strengthens them; the second separator
in a year-month-day date is weaker. Snake-case underscores and elision
apostrophes also join text. Mathematical operators have smaller responses.
A short text tail supplies these contexts, resetting at document boundaries.
Small, idiosyncratic responses to ordinary words and numerals are omitted.
"""
import re
import regex

READS = ()
JOINERS = set('-/–‐‑_\'’=+*<>^−×~.\\') | {'->', '::', ' /', '/\n'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    new_carry = (doc, (tail + token)[-120:])
