                prefix.document_ids[-2] == doc)
    previous = prefix.token_strings[-2] if same_doc else ''
    last = previous[-1:] or ' '
    attached = not (last.isspace() or previous.endswith(('\\n', '\\t', '\\r')))
    digit, letter = last.isdigit(), last.isalpha()
    han = bool(regex.fullmatch(r'\p{Script=Han}', last))
    word = re.search(r'[^\W\d_]+$', previous)
    single = bool(word and len(word[0]) == 1)
    path = bool(re.search(r'/[\w.-]+$', tail))
    date = bool(re.search(r'\d{4}[-/]\d{1,2}$', tail))
    identifier = re.search(r'[\w.-]+$', tail)
    snake = bool(identifier and '_' in identifier[0])
    value = 0.0

    if token in ('-', '‑') and attached:
        value = (0.98 if digit else 0.3 if han else
                 0.83 if letter and single else 1.22 if letter else 0.2)
        if path and letter:
            value = 1.8
        if date and digit:
            value = 0.03
    elif token == '–':
        value = 1.55 if digit else 0.95 if letter else 0.3 if attached else -0.08
    elif token == '‐' and attached:
        value = 0.6
    elif token == '/':
