            value = 1.2
    elif token in ("'", '’'):
        value = 0.08
        if word:
            if word[0] in {'l', 'd', 'dell', 'all', 'nell', 'sull', 'un'}:
                value = 1.03
            elif word[0] in {'s', 'n', 'j', 'c', 'qu'} and previous.startswith(' '):
                value = 0.65
    elif token == '=':
        value = 0.16 if digit else 0.56 if letter else 0.15 if attached else -0.09
    elif token == '+' and attached:
        value = 0.5 if letter or digit else 0.18
    elif token == '*' and attached:
        value = 0.58 if digit else 0.27 if letter else 0.03
    elif token == '<' and attached:
        value = 0.5 if single else 0.39 if digit else 0.22 if letter else 0.03
    elif token == '>' and attached:
        value = 0.21 if digit else -0.23 if letter and not single else 0.0
    elif token == '^' and attached:
        value = 0.13 if digit else 0.05
    elif token.startswith(')') and token[1:] in ('/', '+', '-', '*', '='):
        value = 0.3 if token == ')=' else 0.55
    elif token in ('->', '−', '×', '~'):
        value = 0.3
    elif token in (' /', '/\n'):
        value = 0.2
    elif token == '::' and word and word[0][0].isupper():
        value = 0.35
    elif token == '.':
