Main signals are negative, especially on 'as' after a copula ('is as ...').
Degree adverbs have weaker lexical baselines outside these slots.  The
quantity idioms 'a bit', 'a lot', and 'a whole lot' get separate rules.
The short token history resets at every document boundary.
A separate rule covers the colon in a document-initial Title: header.
"""
READS = ()

BE = set("am is are was were be been being 'm 's 're".split())
SENSE = set("""seem seems seemed seeming look looks looked looking
feel feels felt feeling sound sounds sounded""".split())
CHANGE = set("""become becomes became becoming remain remains remained
get gets got getting gotten""".split())
LINKING = BE | SENSE | CHANGE
NEGATIVE = {"not", "never", "n't", "'t"}
INTERVENING = set("""still just also now sometimes rarely usually always
often already probably certainly therefore really""".split())
PRONOUNS = set("it they he she we you this that".split())
DEGREE = {
    # ordinary context, predicative context
    "as": (0.0, -8.4),
    "so": (-0.25, -3.65),
    "too": (-0.5, -2.15),
    "very": (-0.3, -0.95),
    "particularly": (-0.35, -2.7),
    "especially": (-0.15, -2.4),
    "more": (-0.03, -0.65),
    "less": (-0.2, -1.1),
    "much": (-0.15, -1.3),
    "most": (-0.03, -0.65),
    "pretty": (-0.45, -1.3),
    "quite": (-0.03, -0.5),
    "rather": (-0.03, -0.75),
    "one": (0.02, -1.3),
    "both": (0.0, -2.5),
}


def predicate_before(history):
    """Skip short adverb sequences, or an inverted subject ('is it')."""
    h = list(history)
    while h and h[-1] in INTERVENING:
        h.pop()
    if len(h) > 1 and h[-1] in PRONOUNS and h[-2] in BE:
        h.pop()
    return h[-1] if h else ''


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history, last = (), ''
