    if token.startswith(' ') and word in DEGREE:
        ordinary, predicate = DEGREE[word]
        value = predicate if predicative else ordinary
        if word == 'as':
            if prev in PRONOUNS and head in BE:
                value = -3.5 if head in {'is', 'are', 'was', 'were'} else 0.0
            elif head in SENSE:
                value = -5.5
            elif head in CHANGE:
                value = -3.7
            if prev in NEGATIVE:
                value = -6.7
