                    value = -0.2
            elif prev in {'nearly', 'almost'}:
                value = -8.5
            elif prev in {'quite', 'really'}:
                value = -8.5
            elif prev == 'least':
                value = -6.8
            elif prev in {'near', 'about', 'possibly'}:
                value = -4.5
            elif prev in {'might', 'may', 'come', 'go'}:
                value = -3.7
            elif prev == 'just' and not predicative:
                value = -0.6
            elif prev in {'twice', 'half', 'times'}:
                value = -2.5
        elif prev in NEGATIVE:
            value = {
                'so': -3.5, 'too': -2.6, 'very': -1.25,
                'particularly': -1.6, 'less': -0.5,
            }.get(word, ordinary)
