        elif word == 'much' and prev == 'too':
            value = 0.9
    elif token in {' bit', ' lot'}:
        if prev in {'a', 'an'}:
            head = predicate_before(history[:-1])
            in_predicate = head in LINKING
            if word == 'bit':
                value = -3.6 if in_predicate else -1.4
            else:
                value = -3.1 if in_predicate and head != 'are' else -1.8
        elif word == 'lot' and prev == 'whole':
            value = -4.8
        elif word == 'bit' and prev in {'little', 'tiny'}:
            value = -0.5

    if token == ':' and history == ('title',):
        value = -6.48

    # Do not mistake suffixes inside names for verbs, e.g. the 'am' in Horsham.
    whole = (not last or token[:1].isspace() or
