        return 2.384
    if token == 'int':
        return 1.268
    if token in ('public', 'function'):
        return 1.0
    if token in ('class', 'struct', 'use'):
        return -1.09
    if token == '<!':
        return -2.308
    if token == '//\n':
        return -1.582
    if token == '<|endoftext|>':
        return -1.621
    word = token.strip()
    if not word:
        return 0.06
    if word.startswith('<|'):
        return 0.044
    if word in ('the', 'The', 'this', 'This'):
        return 0.05
    if token == '1':
        return -0.135
    if word.isdecimal():
