    if letters and not regex.fullmatch(r'\p{Latin}+', letters):
        return 8.0 if regex.search(r'\p{Cyrillic}', letters) else 6.3
    if text[0].isupper():
        return 8.7 if token[0].isspace() else 13.3
    if text[0].isalpha():
        return 7.8 if token[0].isspace() else 10.1
    return 6.8


