"""Approximate linking prepositions after descriptive or relational words.

WordNet reduces inflections; the noun groups are hand-selected:
features and parts of a whole, attributes, rules, and information.
Salience and comparison modifiers strengthen the part/feature response. A few linking
participles ('related to', 'associated with') have separate responses.
This is a local lexical approximation, not a syntactic parser.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
FEATURES = {'aspect', 'facet', 'feature'}
PARTS = set('part component constituent element'.split())
ATTRIBUTES = set((
    'property attribute quality characteristic trait peculiarity '
    'limitation advantage disadvantage benefit drawback shortcoming'
).split())
RULES = set('principle rule provision clause requirement'.split())
INFORMATION = set((
    'detail information info fact clue secret question problem concept '
    'topic'
).split())
DEVELOPMENTS = set((
    'trend development advancement breakthrough change step pattern '
    'method challenge phenomenon shift ratio'
).split())
SALIENCE = set((
    'key major important essential integral significant fundamental '
    'central notable vital best weakest interesting other'
).split())
INDEFINITE = {'something', 'anything', 'nothing', 'everything'}

@lru_cache(maxsize=16384)
def bases(word, pos):
    return set(wordnet.base_forms(word, pos)) | {word}


def response(token, previous, before=()):
    prep = token.strip().lower()
    noun = bases(previous, 'noun')
    verb = bases(previous, 'verb')
    salient = bool(set(before[-2:]) & SALIENCE)
    predicate_context = bool(before and before[-1] in {
        'is', 'are', 'was', 'were', 'be', 'been', 'being', 'we', 'they', 'i'
    })
    if prep == 'of':
        if noun & FEATURES:
            return 3.99 if salient else 3.07
        if noun & PARTS:
            return 1.61 if salient else 0.52
        if noun & ATTRIBUTES:
            if 'advantage' in noun and any(
                'take' in bases(w, 'verb') for w in before[-3:]
            ):
                return -0.06
            return 1.09
        if 'principle' in noun:
            return 1.59
        if noun & RULES:
            return 1.46
        if noun & INFORMATION:
            return 0.45
        return 0.01
    if prep == 'in':
        if previous in INDEFINITE:
            return 1.86
        if noun & (INFORMATION | DEVELOPMENTS | ATTRIBUTES | RULES):
            return 0.46
        if previous in {'used', 'employed', 'applied'}:
            return 0.1 if predicate_context else 0.4
        return -0.01
    if prep == 'about':
        if previous in INDEFINITE or previous in {'more', 'lot', 'little'}:
            return 2.31
        if noun & (INFORMATION | ATTRIBUTES | PARTS):
            return 1.14
        if verb & {'know', 'learn', 'say'}:
            return 1.13
        return 0.13
    if prep == 'from':
        if previous in INDEFINITE or previous == 'things':
            return 1.01
        if wordnet.is_a(previous, 'statement') or noun & INFORMATION:
            return 0.55
        return 0.18
    if prep == 'with':
        if previous == 'associated':
            return 0.38 if predicate_context else 0.88
        if noun & {'problem', 'issue'}:
            return 0.56
    if prep == 'to' and previous == 'related':
        return 0.83
    if prep == 'by' and verb & {'provide', 'inspire', 'employ'}:
        return 0.78
    if prep == 'within':
        return 0.22
    if token[:1].isspace() and token.strip().isalpha():
        current = bases(prep, 'noun')
        if current & FEATURES:
            return 0.68 if previous in SALIENCE else 0.18
        if current & {'fact', 'detail'}:
            return 0.3
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    m = re.search(r'([A-Za-z]+)$', tail)
    previous = m.group(1).lower() if m else ''
    before = re.findall(r'[A-Za-z]+', tail[:m.start()].lower()) if m else []
    value = response(token, previous, before)
    return (doc, (tail + token)[-80:]), value

