after a word naming an aspect, property, detail, information or relation fire; the rest stay near 0.
Fitted class weights."""

PREP_BASE = {" about": 0.27, " from": 0.22}          # these fire a little on their own
ASPECT = {" aspect", " aspects", " feature", " features", " characteristic", " characteristics",
          " property", " properties", " facet", " facets", " trait", " traits", " attribute", " attributes",
          " element", " elements", " component", " components", " part", " parts", " principle", " principles",
          " fundamental", " fundamentals", " advantage", " advantages", " disadvantage", " disadvantages",
          " limitation", " limitations", " rule", " rules", " law", " laws", " provision", " provisions",
          " detail", " details", " fact", " facts", " consequence", " subsidiary", " secret", " secrets"}
EMPHASIS = {" key", " important", " certain", " basic", " essential", " central", " main", " major",
            " crucial", " fundamental", " some", " another", " various", " other", " every", " many", " integral"}
DETERMINER = {" the", " a", " an", " this", " that", " these", " those", " its", " their", " his", " her"}
TOPIC = {" something", " nothing", " anything", " everything", " thing", " things", " more", " much", " know",
         " information", " questions", " learn", " lot"}
RELATED = {" related", " associated", " problem", " problems", " issue", " issues", " trends", " advances",
           " changes", " known", " selected", " derived", " data", " results", " provided", " inspired"}
TOPIC_WORDS = {" aspect", " aspects", " facts", " fact", " details", " detail", " regarding", " thereof"}
PREPS = {" of", " about", " in", " from", " with", " to", " by"}
READS = ()

def step(carry, prefix, upstream):
    toks = prefix.token_strings
    docs = prefix.document_ids
    cur = toks[-1]
    if cur in TOPIC_WORDS:
        return None, 0.4
    if cur not in PREPS or len(toks) < 2 or docs[-2] != docs[-1]:
        return None, 0.0
    value = PREP_BASE.get(cur, 0.0)
    prev = toks[-2]
    if prev in ASPECT:
        value += 0.8
