    elif s in ('罚', '罰') and before.endswith('刑'):
        value = 2.7
    elif s == '犯罪':
        value = 0.35
    elif s in ('刑警', '检察院'):
        value = 0.65
    elif s.lower().startswith('criminal') or s.lower() == 'crim':
        value = 0.55
    elif token.lower() == 'riminal' and before.lower().endswith('c'):
