        possessive = previous in (
            'his', 'her', 'my', 'your', 'their', "'s", '’s'
        )
        value = 1.7 if possessive else 0.3
    elif s == 'of':
        if previous in ('voice', 'voices'):
            value = 6.8
        elif previous in ('face', 'faces'):
            value = 2.3
    elif s in ('声', '声音', '的声音'):
        value = 2.0
    elif s and set(s) == {'·'} and len(s) >= 2:
        value = 1.45

    return (doc, new_word, s), value

"""Approximate a document-initial pulse using readable token classes.

The pulse continues through an initial run of identical tokens. Its size
varies with English grammatical class, script/case, digits, whitespace,
and structural markers (headings, questions, Python definitions/docstrings).
After that run, predict zero except for 'en', using recent French function
words as language evidence. Individual word-specific onset differences are
not memorized.
"""
import unicodedata

READS = ()

# Grammatical class, bare-token onset value, space-prefixed onset value.
FUNCTION_CLASSES = [
    ('the', -1.23, 1.65),  # definite article
    ('a an', 1.80, 5.23),  # indefinite article
    ('i me mine my', 0.81, 1.47),  # first person singular
    ('our ours us we', -0.69, 1.48),  # first person plural
    ('you your yours', 1.89, 1.35),  # second person
    ('he her hers him his she', 1.92, 1.54),  # third person singular
    ('it its', -0.09, 2.21),  # neuter pronoun
    ('their theirs them they', 2.88, 2.20),  # third person plural
    ('am are be been being is was were', 1.22, 3.68),  # copula
    ('had has have', 3.98, 3.88),  # have
    ('did do does', 0.43, 0.48),  # do
    # Modal auxiliaries
    ('can cannot could may might must shall should will would', 0.30, 1.92),
    ('of', 1.20, 1.57),  # possessive preposition
    ('to', 6.24, 3.45),  # goal preposition
    ('for', 1.18, 2.59),  # purpose preposition
    ('at in on', 0.99, 2.09),  # location preposition
    ('by from with', 2.25, 2.83),  # accompaniment preposition
    ('and but or', 0.48, 0.20),  # conjunction
    ('as than', 0.32, 1.81),  # comparison
    ('never no not', 2.95, 2.84),  # negation
    ('if unless when while', -0.79, 0.87),  # conditional
    ('that these this those', -0.37, 0.03),  # demonstrative
    ('how what where which who why', 1.99, -0.13),  # interrogative
 ]
FUNCTION_VALUES = {
    word: (bare, spaced)
    for words, bare, spaced in FUNCTION_CLASSES
    for word in words.split()
}

def onset(s):
    """Estimate the response when no earlier distinct token is available."""
    w = s.strip()
    spaced = s[:1].isspace()
    if not w:
        if s == '\t':
            return 2.65
        if s and not s.strip('\n'):
            return min(9.0, 1.8 + 4.2 * (len(s) - 1))
        if '\n' in s:
            return 1.34
        return -0.86 if s == ' ' else -1.31
    if w.startswith('<|'):
        return -0.46
    if '\ufffd' in w:
        return 0.45
    if not w.strip('#'):
        return 6.4 if len(w) == 1 else 4.0
    if w.isdigit():
        if w == '0':
            return -0.86
        if w.isascii() and len(w) == 1:
            return 2.5 - 0.4 * int(w)
        return 0.65
    if w == 'Q':
        return 8.91
    if w == 'def':
        return 12.75
    if w == chr(34) * 3 or w == chr(39) * 3:
        return 12.0 if '\n' in s else 8.0
    if not w.strip('·'):
        return -1.76
    if w.lower() in FUNCTION_VALUES:
        return FUNCTION_VALUES[w.lower()][int(spaced)]
    if all(c in ',.;:' for c in w):
        if w == ',':
            return -0.53
        return 1.78 if w == '.' else 1.89
    if all(c in '\"\'`“”‘’' for c in w):
        return 2.40
    if all(c in '()[]{}' for c in w):
        return 0.64
    if w.isalpha():
        names = ' '.join(unicodedata.name(c, '') for c in w)
        for script, value in SCRIPT_VALUES:
            if script in names:
                return value
        if len(w) == 1:
            return 2.30
        if spaced:
            return 0.47 if w[0].isupper() else 1.30
        return 1.40 if w[0].isupper() else 0.90
    return 1.32


SCRIPT_VALUES = (
    ('CJK', 0.65),
    ('CYRILLIC', 4.59),
    ('GREEK', 1.89),
    ('ARABIC', 0.25),
    ('HANGUL', 2.00),
    ('HIRAGANA', 1.99),
    ('KATAKANA', 1.81),
)
FRENCH_MARKERS = frozenset(
    'le les du des une est vous dans cette avec aux sont'.split()
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    first = carry is None or carry[0] != doc
    french = 0.0 if first else carry[1] * 0.99
    s = prefix.token_strings[-1]
    w = s.strip()
    if s[:1].isspace() and w.lower() in FRENCH_MARKERS:
        french += 1.0
    initial_run = first or (carry[3] and carry[2] == token)
    if initial_run:
        value = onset(s)
    elif w in {"'en", '’en'}:
        value = 0.97
    elif w.lower() == 'en':
        ordinary = 0.1 if s[:1].isspace() or w == 'En' else 0.0
        value = 1.2 if french > 1.2 else ordinary
    else:
        value = 0.0
    return (doc, french, token, initial_run), float(value)

programs.haiku:
"""layers.1.mlp.down_proj:1244 - a document-opening detector.

This component is almost silent inside a document. It fires on the first token of
each document (the token right after <|endoftext|>, or the first token of a row), and
how strongly depends only on what that first token is:

- markup openers (a heading '#', a blank line, a code fence) are strongly positive;
- a lowercase single letter, or a Cyrillic letter, is positive;
- a capital single letter, a function word with a leading space (" a", " is", " to"),
  or a capitalised or spaced word is mildly positive;
- a digit or other symbol is weakly positive;
- common sentence-opening English words ("The", "Today", "New", "Since") are negative.

Predicted value: the group's mean activation at document starts, 0 everywhere else.
"""

import unicodedata

READS = ()

MARKUP = {"#", "##", "\\", "\n\n", ".\n\n", '"""\n', "'''\n"}
FUNCTION_WORDS = {" a", " to", " is", " the", " in", " of", " for", " on", " it", " and",
                  " that", " with", " as", " by", " or", " from", " at", " be", " are", " was"}
OPENING_WORDS = {"The", "This", "Today", "New", "Since", "If", "Which", "When", "We",
                 "As", "It", "At", "Why", "But", "And"}

GROUP_MEAN = {
    "markup": 6.0, "cyrillic": 4.3, "letter_low": 3.1, "letter_up": 2.0,
    "function_word": 2.0, "capitalised_word": 1.5, "spaced_word": 1.25,
    "digit": 0.75, "other": 0.7, "opening_word": -1.3,
}


def group(token):
    word = token.strip()
    if token in MARKUP:
        return "markup"
    if not word:
        return "other"
    if "CYRILLIC" in unicodedata.name(word[0], ""):
        return "cyrillic"
    if word.isdigit():
        return "digit"
    if len(word) == 1 and word.isalpha():
        return "letter_low" if word.islower() else "letter_up"
    if token in FUNCTION_WORDS:
        return "function_word"
    if token in OPENING_WORDS:
        return "opening_word"
    if token.startswith(" ") and word.isalpha():
        return "spaced_word"
    if word[:1].isupper() and word.isalpha():
        return "capitalised_word"
    return "other"


def step(carry, prefix, upstream):
    t = prefix.position
    starts_document = t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]
    if not starts_document:
        return None, 0.0
    return None, GROUP_MEAN[group(prefix.token_strings[t])]

programs.sol:
"""Negative responses to short 'ob' spellings and their subword continuations.

Latin ob and Cyrillic об are strongest in small fragments, not in long
whole words. The spellings job/jobs are especially strong. An o
followed by a b-starting fragment also triggers the response: OBS..., for
example. A narrow secondary response marks an opening 'Title:' label.
"""

import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, position = '', 0
    else:
        previous, position = carry[1:]
    text = prefix.token_strings[-1]
    word = text.strip()
    lower = word.lower()
    prev = previous.strip()
    separated = bool(text and text[0].isspace())
    letters = word.isalpha()
    value = 0.0

    # The spellings job/jobs, with case and leading-space adjustments.
    bare = lower.lstrip('._(')
    if bare in ('job', 'jobs'):
        if not separated:
            value = -5.3 if word[:1].isupper() else -7.0
        else:
            value = -3.8
            if word[:1].isupper():
                value -= 2.5 if lower.endswith('s') else 1.1
    elif 'ob' in lower:
        if letters and len(lower) <= 3:
            if lower.endswith('ob'):
                value = -1.6 if separated else -3.0
            elif lower.startswith('ob'):
                value = -3.2 if lower[-1] in 'os' else -1.0
                if separated:
                    value *= 0.6
        else:
            value = -0.15
    elif 'об' in lower:
        value = -0.25 if separated else -1.4
        if len(lower) > 3:
            value *= 0.2

    # Join an o/b pair across a token boundary. Pro- is a weak case.
    if not separated and prev.lower().endswith(('o', 'о')):
        if lower.startswith(('b', 'б')):
            amount = 2.0 if len(word) <= 4 else 0.2
            if len(prev) >= 4 and len(word) <= 3:
                amount = 5.0
            if word.isupper() and len(word) <= 2:
                amount = 6.3
            if prev.lower().endswith('pro'):
                amount *= 0.2
            if word.istitle() and len(word) > 1:
                amount *= 0.1  # a CamelCase boundary is not a joined fragment
            value -= amount

    # A short continuation of an ob-ending fragment retains some response.
    if not separated and letters and len(word) <= 3:
        if prev.lower().endswith(('ob', 'об')) and len(prev) <= 4:
            value -= 1.4

    # A job spelling split between fragments is stronger than a whole word.
    if not separated and prev.lower() in ('j', 'jo'):
        if (prev + word).lower() in ('job', 'jobs'):
            value = -10.0

    if position == 1 and prev == 'Title' and word == ':':
        value = -12.5
    # Remember the unfinished word, rather than just the previous token.
    joined = previous + text
    match = re.search(r'[^\W\d_]+$', joined)
    unfinished = match.group()[-32:] if match else ''
    return (doc, unfinished, position + 1), value

programs.haiku:
"""Layer 1, MLP down-projection component 1246: a "-ob / job" spelling detector.

It is silent on almost every token. It goes strongly negative on the bare
pieces that spell the sounds "ob" and "job":

  * "BS" that completes "OBS" / "JOBS" when split across tokens, as in
    "<tool_response>\\nO|BS|ERVATION" or "JO|BS Act" (strongest, about -6 to -12);
  * "job" / "jobs" as a whole word or piece (about -4);
  * other pieces ending in "ob" (ob, mob, rob, Bob, lob, sob) (about -2);
  * other pieces that merely contain "ob" (about -0.1 to -0.4).

Everything else predicts 0. It reads only the current token and the one before it.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    before = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    if token.strip() == "BS":
        # "BS" right after a lone "O" or "JO" completes "OBS" / "JOBS"
        value = -6.4 if before in ("o", "jo") else -0.35
    elif word in ("job", "jobs"):
        value = -4.3
    elif word.endswith("ob"):
        value = -1.8
    elif "ob" in word:
        value = -0.15
    else:
        value = 0.0
    return None, value

programs.sol:
"""A detector for relational derivation, especially noun -> adjective -ional.

The response is negative. A separately tokenized ending (division + al,
compos + itional) is stronger than the same ending inside a whole word.
The carry retains only the unfinished word, and resets at document boundaries.
Related Romance and Russian adjective endings have parallel rules.
A small positive rule recognizes "reason for/why". Common -itional words
are attenuated using word frequency. Other word-specific variation is omitted.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency
from wordnet import parts_of_speech

READS = ()
LETTERS = re.compile(r'[^\W\d_]+$', re.UNICODE)


@lru_cache(maxsize=65536)
def response(token, previous):
    w = token.strip().lower()
    attached = bool(previous and token[:1].isalpha())
    joined = previous + w if attached else w
    if previous in ('reason', 'reasons'):
        if w == 'for':
            return 3.9
        if w == 'why':
            return 2.1
    if attached:
        if previous.endswith(('ion', 'ment')):
            if w in ('al', 'ally', 'ality', 'alities', 'als', 'nal', 'nally'):
                return -6.0 if previous.endswith('ion') else -2.7
            if w in ('ary', 'arily', 'aries', 'ist', 'ists', 'ism', 'ately'):
                return -3.0
        if previous.endswith(('ional', 'ionally', 'ionality')):
            return -1.1
        if joined.endswith('циона'):
            return -5.3
        if joined.endswith('цион'):
            return -2.2
        if joined.endswith('ональ'):
            return -3.3
        if re.search(r'(ональ|ционн).{1,6}$', joined):
            return -2.1
        if previous.endswith(('tion', 'sion', 'cion', 'zion', 'jon')):
            if w in ('nelle', 'nel', 'nels', 'nelles', 'nal', 'ale',
                     'ales', 'aux', 'el', 'ella', 'elle', 'alt', 'ali', 'ais'):
                return -4.2

    # Adverbs inherit the adjective's ending.
    base = w[:-2] if w.endswith('ly') else w
    if base == 'ational':
        return -4.2
    if base == 'itional':
        return -6.1
    if base == 'ional':
        return -4.6
    # Spanish/Italian inflections of the same relational ending.
    if re.search(r'ional(es|e|i|s)$', base):
        return -2.0
    if base.endswith('ionary') and 'adjective' in parts_of_speech(base):
        return -2.0
    if base.endswith('itional'):
        return -0.7 if zipf_frequency(base, 'en') > 4.5 else -3.5
    for ending, value in (
        ('ational', -1.65), ('tional', -2.47),
        ('sional', -0.99), ('ional', -3.14), ('ural', -0.28),
        ('ental', -0.47), ('orial', -0.38),
    ):
        if base.endswith(ending):
            return value
    return -0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = response(token, previous)
    text = previous + token if token[:1].isalpha() else token
    match = LETTERS.search(text)
    word = match.group().lower()[-80:] if match else ''
    return (doc, word), value

"""Spelling at a token edge, especially an unfinished consonant cluster in c.

A separately tokenized c after r/n/y responds much more than c inside a
finished word. The preceding spelling changes its strength: tr+c is especially
strong, er/ur+c weaker. Short rc/yc pieces and franc-/marc-/conc- stems also
respond. Opposing ky/koz clusters and document-opening comments/CRs are
included; unmatched tokens get zero. These are local spelling heuristics.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    history = '' if first else carry[1]
    previous = '' if first else carry[2]
    only_returns = first or carry[3]
    s = token.strip()
    lower = s.lower()
    before = previous[-1:].lower()
    pair = previous[-2:].lower()
    value = 0.0

    if token in ('c', 'C'):
        if before == 'r':
            value = 4.5
            if pair == 'tr':
                value = 9.0
            elif pair in ('ar', 'ir', 'or'):
                value = 5.9
            elif pair in ('er', 'ur'):
                value = 2.9
        elif before == 'n':
            value = 4.7 if pair == 'on' else 2.7
        elif before == 'y':
            value = 3.8
        elif before == 'l':
            value = 4.5 if pair == 'yl' else 0.6
        elif before == 'w':
            value = 2.1
        elif before == 'k':
            value = 2.6 if pair == 'rk' else 0.8
        else:
            value = {'o': 1.8, 'g': 1.3, 'x': 1.6,
                     't': 0.3, 'm': 0.4, 'q': 1.9, 'v': 0.7}.get(before, 0.0)
        if token == 'C' and previous[-1:].islower():
            value = 0.5
        if history.endswith('\\n'):
            value = 0.0
    elif token in ('č', 'Č'):
        value = 3.8 if before == 'n' else 0.0
    elif token == 'ч':
        value = 1.0 if before == 'н' else 0.0
    elif lower.endswith('c'):
        if lower == 'rc':
            value = 2.1 if s.isupper() else 3.3
        elif lower.endswith(('franc', 'marc')):
            value = 3.0
        elif re.search(r'[aeio]rc$', lower):
            value = 2.3 if s[:1].isupper() else 1.0
            if token == 'arc' and history.endswith('m'):
                value = 4.5
        elif lower.endswith('rc'):
            value = 0.25
        elif lower == 'yc':
            value = 2.2
            if previous.lower().endswith('pol'):
                value = 4.7
            elif previous == 'M':
                value = 3.8
        elif lower.endswith('yc'):
            value = 0.1 if s.isupper() else 1.0
        elif lower.endswith('onc'):
            value = 2.3 if s[:1].isupper() else 1.15
    elif token in ('yp', 'yl', 'yn', 'ye') and before == 'k':
        if token == 'yp':
            value = -3.0 if pair == 'sk' else -1.6
        elif token == 'yl':
            value = -2.5 if pair == 'lk' else -1.0
        else:
            value = -1.0
    elif token == 'oz' and before == 'k':
        value = -5.0 if pair == 'lk' else -1.3
    elif token == 'z' and pair == 'ko':
        value = -3.8

    # A dot-prefixed spelling ending in rc often denotes a configuration file.
    if token in ('rc', 'c') and re.search(r'\.[a-z]+rc$', history + token):
        value = 9.5 if pair == 'tr' else 5.7
    if first and token == '//\n':
        value = -12.0
    if only_returns and token == '\r':
        value = -7.7
    return (doc, (history + token)[-24:], token,
            only_returns and token == '\r'), value

programs.haiku:
"""The letter pairs r-c, n-c and y-c inside words (v5).

layers.1.mlp.down_proj:1248 reads the layer-1 MLP hidden state and writes into the
residual stream. Its activation is large when the current token completes a "c" that
follows a consonant inside a word: the bare token "c" (or "C") after a word piece ending in
r, n or y ("tr|c", "por|c|ine", "char|c", "gly|c|emia", "Zajon|c", "inter|c|ultural"),
or a fragment that already holds such a pair ("rc", "yc", "arc", "Marc", "franc", "ARC").
The bare "c" after a vowel is near zero, and so is a "c" that starts a word, follows a
space, a digit or punctuation. Whole English words with a c (can, which, code) stay near
zero. A few fragments that end in y, z or o (yp, oz, yz) push it negative.

The program looks back at the single token before the current one; it keeps no state.
"""

READS = ()

# How strongly a bare "c" responds, by the letter that ends the piece before it.
C_AFTER = {"r": 5.0, "y": 4.0, "n": 4.0, "q": 2.0, "w": 1.5, "g": 1.5, "k": 1.0, "l": 1.0}
# Fragments that already contain such a pair.
PAIR_FRAGMENTS = {
    "rc": 3.0, "yc": 2.5, "RC": 2.5, " RC": 2.5, " rc": 3.0, "ARC": 3.0, " ARC": 2.5,
    "Marc": 2.5, " Marc": 3.0, "merc": 3.5, " Franc": 3.0, " franc": 3.0, "GC": 1.5,
    "arc": 1.3, " arc": 0.6, "erc": 0.7, "irc": 0.7, "orc": 0.8, "IRC": 2.5,
    "conf": 1.0, "conc": 1.0, " conc": 1.1, " Conc": 2.3, "cv": 1.3, "cs": 0.4, "ci": 0.4,
}
NEGATIVE_FRAGMENTS = {"yp": -1.1, "oz": -0.65, "yz": -1.5, "YL": -1.4, "onz": -1.1, "rp": -0.7}


def _piece_before(prefix):
    """The token just before this one, if it is a letter piece in the same document."""
    if len(prefix.token_strings) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return ""
    piece = prefix.token_strings[-2].strip()
    return piece if piece.isascii() and piece.isalpha() else ""


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in ("c", "C"):
        before = _piece_before(prefix)
        value = C_AFTER.get(before[-1:].lower(), 0.0) if before else 0.0
    elif token in PAIR_FRAGMENTS:
        value = PAIR_FRAGMENTS[token]
    elif token in NEGATIVE_FRAGMENTS:
        value = NEGATIVE_FRAGMENTS[token]
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""A sparse lexical response centered on 亲/親 (kin, close, personally).

Isolated characters fire more strongly than compounds. Body, respect,
first-hand involvement, and English 'personally'/'own' are weaker cues.
Recent kana lowers the response to 親. Some completed UTF-8 fragments
(친, 희, 謹) have separate strengths. Leading nonbreaking-space padding
is positive; a document-opening empty // comment is negative.
This approximates a lexical cluster, not all of the component's activity.
"""
import codecs
import regex

READS = ()
KANA = regex.compile(r'[\p{Script=Hiragana}\p{Script=Katakana}]')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        decoder = codecs.getincrementaldecoder('utf-8')('ignore')
        recent = ''
        leading_space = True
    else:
        _, decoder, recent, leading_space = carry
    fragmented = bool(decoder.getstate()[0])
    text = decoder.decode(prefix.token_bytes[-1])
    word = text.strip()
    value = 0.0

