        value = 6.8 if japanese else 8.8
    elif word == '친':
        value = 14.5 if fragmented else 2.0
    elif word == '희' and fragmented:
        value = 4.0
    elif word in ('亲自', '亲身', '親自', '親身'):
        value = 4.4
    elif any(ch in word for ch in '亲親'):
        value = 1.4
        if word in ('母亲', '父亲', '母親', '父親'):
            value = 2.0
        elif word in ('亲爱', '亲爱的', '親愛', '親愛的'):
            value = 0.5
    elif word == '敬':
        value = 4.6
    elif word in ('尊敬', '致敬', '尊'):
        value = 0.7
    elif word in ('谨', '謹'):
        value = 5.5 if word == '謹' and fragmented else 1.0
    elif word == '身':
        value = 0.65
    elif word in ('身体', '身體', '全身', '一身'):
        value = 0.5
        if recent.endswith(('亲', '親', '切')):
            value = 3.1
    elif word in ('本身', '自身', '健身', '身上'):
        value = 0.3
    elif word == 'personally':
        value = 1.95 if text.startswith(' ') else 0.1
    elif word == 'Personally':
        value = 0.75 if text.startswith(' ') else 0.1
    elif word == 'own':
        value = 0.21 if text.startswith(' ') else 0.0

    # Leading nonbreaking-space padding has a separate boundary response.
    if leading_space and text and text.isspace() and '\xa0' in text:
        count = text.count('\xa0')
        if ' ' in text:
            value = 1.3 if count == 1 else 1.9
        else:
            value = 2.0 / count ** 0.5
    elif leading_space and text == '//\n':
        value = -3.6
    leading_space = leading_space and (not text or text.isspace())
    return (doc, decoder, (recent + text)[-48:], leading_space), value

"""A local parenthetical-annotation detector.

Give strong positive responses to birth labels, Latin explanatory abbreviations,
figure references, media qualifiers, signature labels, and Lisp binding forms
at the opening of parentheses. Other opening words get a much weaker response.
Document starts have a small negative baseline; an initial 'Title:' has a
separate negative response. These are approximations, not a full token table.
"""
import re
READS = ()
MEDIA = {'film', 'album', 'song', 'novel', 'band', 'tv', 'series', 'book'}
BINDINGS = {'setq', 'setf', 'define', 'defun'}
C_TYPES = {'void', 'int', 'char', 'float', 'double', 'long', 'short', 'id'}

def predict(carry, token, doc):
    if carry is None or carry[0] != doc:
        tail, position = ('', 0)
    else:
        tail, position = (carry[1], carry[2] + 1)
    token = token.replace('（', '(').replace('）', ')')
    word = token.strip()
    opening = bool(re.search('\\(\\s*$', tail))
    embedded = re.search('\\(([^\\s()]*)$', token)
    if embedded and embedded[1]:
        word, opening = (embedded[1], True)
    lower = word.lower()
    value = -0.0
    if position == 0:
        value = -0.331 if word.istitle() else -0.194
    if opening:
        value = 0.022
        if len(word) >= 3 and word.isalpha():
            value = 0.093
        if word == 'born':
            value = 2.11
        elif lower in MEDIA:
            value = 1.184
        elif lower in {'figure', 'fig', 'table', 'eq', 'equation'}:
            value = 1.276 if lower == 'figure' else 0.731
        elif re.fullmatch('[IVX]{2,}', word):
            value = 2.309
        elif re.fullmatch('[ivx]{2,}', word):
            value = 0.761
        elif word == 'talk':
            value = 5.137
        elif word in {'UTC', 'GMT'}:
            value = 2.346
        elif word == 'HEAD':
            value = 3.035
        elif word in BINDINGS:
            value = 3.258
        elif word == 'let':
            value = 1.285
        elif word in C_TYPES and re.search('[-+]\\s*\\(\\s*$', tail):
            value = 1.709
        elif word.startswith('?:'):
            value = 3.994
    if re.search('\\(\\s*e$', tail) and token.startswith('.g'):
        value = 1.815
    elif re.search('\\(\\s*i$', tail) and token.startswith('.e'):
        value = 0.794
    elif tail.endswith(' et') and word == 'al':
        value = 0.028 if '(' in tail and ')' not in tail else -0.24
    elif word in {':', '|'} and re.search('\\(\\s*[^\\s()]{2,15}$', tail):
        value = 0.108
    if position == 1 and tail == 'Title' and (token == ':'):
        value = -3.977
    return ((doc, (tail + token)[-50:], position), value)

def step(carry, prefix, upstream):
    carry, value = predict(carry, prefix.token_strings[-1], prefix.document_ids[-1])
    return (carry, value)

