"""Parenthetical asides and document starts.

Fires on the first word inside an opening bracket: strongly when the word starts a stock
aside ("(born", "(Fig.", "(ii)", "(e.g.", "(i.e."), weakly for any other word. Goes slightly
negative on the first token of each document."""
READS = ()

OPENERS = {" (", "(", "（"}
BORN = {"born"}
FIGURE = {"Fig", "Figure", " Fig", " Figure", "FIG"}
ROMAN = {"ii", "iii", "II", "III"}
DOC_START = -0.24
WORD_AFTER_OPEN = 0.14


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, DOC_START
    if prev in OPENERS:
        if cur in BORN:
            return None, 2.3
        if cur in FIGURE or cur in ROMAN:
            return None, 1.0
        if cur.strip()[:1].isalpha():
            return None, WORD_AFTER_OPEN
        return None, 0.0
    if prev == "e" and cur == ".g":
        return None, 1.9
    if prev == "i" and cur == ".e":
        return None, 0.95
    return None, 0.0

"""layers.1.mlp.down_proj:1251 -- a negative "nc / nz" loanword-ending detector.

The component is near zero almost everywhere. It goes strongly negative on a few
kinds of token, and the largest negatives are word pieces that finish a Latin- or
Romance-style noun ending in -ance / -ence / -enza / -anza / -encia (and -nce, -nza
written in katakana), e.g. "influ|ence", "urgen|za", "esigen|ze", "ン|ス".

 1. Strong: the piece is a Romance noun ending -enza, -anza, -encia, -ancia, -ência,
    -encias, -ancias  (about -2).
 2. Medium: the piece is -ance, -ence, -anc, -anz, -enz, -ances, -ancy, -ency, -ncy,
    -enci  (about -0.75); -enc and -ences are weaker (about -0.25).
 3. Sibilant: after an "n" inside the same word (the "nc"/"nz" of -nce, -nza), a
    following piece z, za, ze, ce, ca, ces, ça, ç  (about -0.8).
 4. Katakana ス after ン (the "-nse" sound of loanwords such as チャンス) (about -3).
 5. Loop keywords that open a line of code: "for" (about -0.7), "while", "try", "do".
 6. Chat markup: the role token "assistant" (+0.45) and "</tool_call>" (+0.2) are small
    constant positives.

Everything else predicts 0.
"""

READS = ()

STRONG = {"enza", "anza", "encia", "ancia", "ência", "encias", "ancias", "ienza"}
MEDIUM = {"ance", "ence", "anc", "anz", "enz", "ances", "ancy", "ency", "ncy", "cence",
          "arence", "encer", "enze", "enci"}
WEAK = {"enc", "ences"}
SIBILANT = {"za", "ze", "ce", "ca", "ces", "ça", "ç", "ças"}
LOOP = {"for": -0.7, "while": -0.35, "try": -0.55, "do": -0.3}


def step(carry, prefix, upstream):
    # carry = (line_start, word): line_start is True when only whitespace has come since the
    # last newline (or document start); word is the letters of the current word so far.
    line_start, word = carry if carry is not None else (True, "")
    if len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        line_start, word = True, ""
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    piece = token.strip()
    low = piece.lower()
    value = 0.0
    if line_start and piece in LOOP:
        value = LOOP[piece]
    elif piece == "assistant":
        value = 0.45
    elif piece == "</tool_call>":
        value = 0.2
    elif low in STRONG:
        value = -2.0
    elif low in MEDIUM:
        value = -0.75
    elif low in WEAK:
        value = -0.25
    elif low in SIBILANT and "n" in word:
        value = -0.8
    elif piece == "ス" and previous.endswith("ン"):
        value = -3.0
    # update the carry for the next token
    if "\n" in token:
        line_start = token.split("\n")[-1].strip() == ""
    else:
        line_start = line_start and token.strip() == ""
    # letters of the current word: restart after any non-letter, else extend
    if token and not token[-1].isalpha():
        word = ""
    elif token.strip() and token.strip()[-1:].isalpha():
        letters = "".join(ch for ch in token.lower() if ch.isalpha())
        word = letters if token[:1] in " \t\n\r" else word + letters
    return (line_start, word), value

