"""A document-opening response, especially the metadata label `Title:`.

At row/document starts, estimate the first response from token shape:
short ASCII-letter tokens and digits tend to be more positive than longer ones.
A standalone colon token after initial, case-sensitive `Title` spikes.
Otherwise predict the near-zero background, not individual word effects.
"""
READS = ()


def opening_value(token):
    word = token.strip()
    if word.isascii() and word.isalpha():
        length = len(word)
        if length == 1:
            return 0.47
        if length <= 3:
            return 0.24 if token.startswith(' ') else 0.38
        if length <= 6:
            return 0.10
        return -0.07
    if word.isascii() and word.isdigit():
        return 0.34
    if not word:
        return 0.10
    return 0.18


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    at_start = carry is None or carry[0] != doc
    opening_title = at_start and token == 'Title'

    if opening_title:
        value = 0.534
    elif at_start:
        value = opening_value(token)
    elif carry[1] and token == ':':
        value = 3.744
    else:
        value = -0.0012
    return (doc, opening_title), value

"""Estimate activations from short, recognizable phrases.

Positive cues include calendar dates, classification links, other selected
'of' constructions, and 'of' spellings in code or split words. Negative cues
include web-preview text, URL/import/front-matter syntax, PHP opening
whitespace, and diagnostics. These rules leave weaker lexical effects at a
small background value; they are not a complete activation reconstruction.
Remember 100 characters and whether this document opened as PHP, resetting
both at document boundaries.
"""
import calendar
import re

READS = ()
MONTHS = frozenset(calendar.month_name[1:] + calendar.month_abbr[1:] + ['Sept'])
MONTH_DATE = re.compile(
    r'\b(?:' + '|'.join(MONTHS) + r')\.?\s+\d{1,2}$'
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, php = '', False
    else:
        _, tail, php = carry
    token = prefix.token_strings[-1]
    value = -0.002
    word = tail.rstrip().rsplit(' ', 1)[-1].split('\n')[-1]

    if token in ('st', 'nd', 'rd', 'th') and MONTH_DATE.search(tail):
        value = 1.37
    elif token == ' of':
        if re.search(r'\d(?:st|nd|rd|th)$', tail):
            value = 0.3
        elif word in MONTHS:
            value = 0.95
        elif word in ('instance', 'subclass'):
            value = 0.4
        elif word in ('Board', 'Club', 'Council', 'Committee'):
            value = 0.3
        elif word in ('Act', 'Bill'):
            value = 0.4
        elif word in ('north', 'south', 'east', 'west'):
            value = 0.27
        elif word in ('part', 'piece', 'snippet', 'example', 'examples'):
            value = 0.15
        elif word in ('year', 'years', 'terms'):
            value = -0.18
    elif token in (' a', ' an') and word.lower() == 'such':
        value = 0.27
    elif token == '.com' and tail.endswith('github'):
        value = -0.5
    elif token == 'www' and tail.endswith('://'):
        value = -0.23
    elif token == 'import' and tail.endswith('\n'):
        value = -0.2
    elif token == ':' and tail.endswith('\ntitle') and '---\n' in tail:
        value = -2.17
    elif token.strip(' (<') == 'typeof' or token == 'InstanceOf':
        value = 1.37
    elif token in ('f', ' f') and word.strip('\x00') == 'o':
        value = 1.5
    elif token == 'nof' and tail.endswith('\\'):
        value = 1.8
    elif token == ' shows' and tail.endswith('This preview'):
        value = -3.45
    elif token in (' page', ' pages') and tail.endswith('This preview shows'):
        value = -1.8
    elif token == '\n\n' and tail.endswith('<?php'):
        value = -1.35
    elif token == 'abstract' and php:
        value = 1.95
    elif token == ' abstract' and word in ('public', 'protected', 'private'):
        value = 0.9
    elif token == 'back' and tail.endswith('Trace'):
        value = -1.0
    elif token == 'info' and tail.endswith('debug'):
        value = -0.78
    elif token == '一览' and tail.endswith('目录'):
        value = -1.15

    tail = (tail + token)[-100:]
    php = php or '<?php' in tail
    return (doc, tail, php), value

programs.haiku:
"""Activation of layers.1.mlp.down_proj:1253, predicted from the current and recent tokens.

The component is a sparse "of" detector with a few side cases. It is near zero on most
tokens. It is strongly positive on the word "of" when it is broken or disguised (a split
"o f", code words such as "typeof" and "instanceof"), and on "of" in a date ("in April of
2010") or in Wikidata-style "instance of". It is positive on the ordinal suffix of a day
number ("June 7th"), and strongly negative on the boilerplate "This preview shows N pages".
Web and code tokens (".com", "www", "org", "import", "info") are slightly negative. Every
other token is predicted as 0, and so is the first token of each document.
"""

READS = ()

MONTHS = {"January", "February", "March", "April", "May", "June", "July", "August",
          "September", "October", "November", "December"}
CODE_OF = {"typeof", " typeof", "instanceof", " instanceof", "indexOf", " indexOf",
           "sizeof", "(typeof", "(sizeof", "feof"}
DOMAIN = {".com", "www", " org", "import", "info"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    prev = toks[-2] if len(toks) > 1 else ""
    if len(toks) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    recent = [t.strip() for t in toks[-4:-1]]
    if cur == " of":
        if prev.strip() in MONTHS:
            return None, 0.9
        if prev == " instance":
            return None, 0.4
        return None, 0.0
    if cur in (" f", "f") and prev in (" o", "fo"):
        return None, 1.6
    if cur in CODE_OF:
        return None, 1.0
    if cur == " shows" and prev == " preview":
        return None, -3.5
    if cur in (" pages", " page") and prev == " shows":
        return None, -2.0
    if cur in ("th", "st", "nd", "rd") and prev.strip().isdigit():
        return None, 1.2 if any(t in MONTHS for t in recent) else 0.2
    if cur in DOMAIN:
        return None, -0.15
    return None, 0.0

programs.sol:
"""A small structural-boundary predictor, not a lexical activation lookup.

It distinguishes document-opening punctuation and indentation, title-like first
line endings, and HTTP versus HTTPS scheme separators. Ordinary text is near zero;
opening words are mostly left unexplained, apart from grammatical and code classes.
A homogeneous repeated prefix keeps its opening response, including dot decorations.
"""
import re
from collections.abc import Mapping

READS = ()


def opening_value(s):
    word = s.strip().lower()
    if s.startswith('<|'):
        return -0.25
    if s and not s.strip(' '):
        return 0.02 if len(s) == 1 else 1.7 if len(s) == 2 else 2.8
    if s == '\u00a0':
        return 1.7
    if s.isspace():
        if '\n' in s:
            if s.strip('\n\r'):
                return 1.0 if s.count('\n') == 1 else 0.37
            return 0.14 if s.count('\n') == 1 else -0.65
        return 0.03 if len(s) == 1 else 0.7
    if len(s) >= 2 and set(s) == {'·'}:
        return 3.8
    if word.isdigit():
        return -0.32
    if word in {'and', 'or'}:
        return 1.22 if s.startswith(' ') else 0.35
    if word in {'not', 'cannot'}:
        return -0.8
    if word == 'the':
        return 0.24
    if word == 'a':
        return 0.1
    if word in {'package', 'import', 'using'}:
        return -0.55
    if word in {'def', 'function'}:
        return 1.8
    if s.lstrip().startswith(('\"', '“')) and not s.lstrip().startswith('\"\"\"'):
        return 1.3 if s.startswith(' ') else 2.0
    if any(c.isalnum() for c in s):
        if s in ('\\n', '\\t'):
            return 3.8
        return -0.18 if len(word) == 1 else 0.0
    if '\\"' in s:
        return 3.8
    if word in {'"', '“', '”'}:
        return 1.3 if s.startswith(' ') else 2.0
    if word == "'":
        return 0.65
    if word in {'.', '?', '!', '。'}:
        if '\n' in s:
            return 2.4 if s.count('\n') == 1 else 0.3
        return 1.3
    if word == ';':
        return 1.0
    if word == ':':
        return 0.65 if '\n' in s else 0.14
    if word in {'(', '[', '{'}:
        return -0.25
    if word in {')', ']', '}'}:
        return 0.65
    if word in {'()', '[]'}:
        return 2.3
    if word == '*':
        return 3.0 if s.startswith(' ') else 1.0
    if word in {'$', '\\', '|', '_', '__'}:
        return -0.5
    return 0.15


def title_break(line, s, age):
    title = (line + s.split('\n')[0]).rstrip()
    start = title.lstrip('# ').lstrip('"“')
    if not (2 <= age <= 65 and title and start and start[0].isupper()):
        return 0.0
    if (title[0].isspace() or len(title) > 350
            or any(c in title for c in '{};=\\`|<>')
            or re.search(r'[.。;:}]$', title)):
        return 0.0
    if s == '\n\n':
        return 1.1
    if s == '\n':
        return 0.5 if '.' not in title else 0.25
    return 0.65 if s.count('\n') > 1 else 0.3


def step(carry, prefix, upstream: Mapping):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        age, line, first_line, prev, repeated = 0, '', True, '', True
    else:
        _, age, line, first_line, prev, repeated = carry
        repeated = repeated and s == prev
    value = 0.0
    if age == 0 or repeated:
        value = opening_value(s)
    elif s == '://':
        value = 1.1 if prev.strip().lower() == 'https' else 0.4
    elif prev == '://':
        value = 0.20
    elif '\n' in s and first_line:
        value = title_break(line, s, age)
    if '\n' in s:
        first_line = False
    if first_line:
        line = (line + s)[-1000:]
    return (doc, age + 1, line, first_line, s, repeated), value

programs.haiku:
"""Layer 1 MLP down_proj, component 1254: a mostly silent direction with three spikes.

Most positions sit near zero. The component is large in three situations:

1. The first token of a document (positions restart at each document, so this is the
   first token of every packed document, and of the row). There the activation depends
   only on that token. Whitespace, punctuation and brackets, quotes and code/markup
   symbols push it up; digits push it down; words barely move it.
2. The "://" of a URL: strong after "https" (about 1.1), weaker after "http" (about 0.4).
3. A paragraph break "\\n\\n" in the first 20 tokens of a document, i.e. the blank line
   just after a title or first line (about 0.4).

Everywhere else the program predicts 0.

Main program: `step` counts each token's position inside its document (carry), then
applies the three rules above in order.
"""

import unicodedata

READS: tuple[str, ...] = ()

# Activation at a document's first token, by the kind of token it is.
FIRST_TOKEN = {"space": 0.6, "punct": 0.7, "symbol": 0.0, "digit": -0.3, "word": -0.1}
HTTPS_SCHEME = {"https", '"https'}
HTTP_SCHEME = {"http"}
PARAGRAPH_BREAK = "\n\n"
EARLY_TOKENS = 20


def token_kind(text: str) -> str:
    """Rough kind of a token, from its first visible character."""
    body = text.strip()
    if not body:
        return "space"
    first = body[0]
    if first.isdigit():
        return "digit"
    if first.isalpha():
        return "word"
    if unicodedata.category(first).startswith("P"):
        return "punct"
    return "symbol"


def step(carry, prefix, upstream):
    # carry: this token's position inside its document, from the previous step (None at a row start).
    ids = prefix.document_ids
    if carry is None or len(ids) < 2 or ids[-2] != ids[-1]:
        position = 0  # a new document (or the row's first token): positions restart
    else:
        position = carry + 1

    text = prefix.token_strings[-1]
    if position == 0:
        value = FIRST_TOKEN[token_kind(text)]
    elif text.strip() == "://":
        scheme = prefix.token_strings[-2].strip()
        if scheme in HTTPS_SCHEME:
            value = 1.1
        elif scheme in HTTP_SCHEME:
            value = 0.4
        else:
            value = 0.0
    elif text == PARAGRAPH_BREAK and position < EARLY_TOKENS:
        value = 0.4
    else:
        value = 0.0
    return position, float(value)

programs.sol:
"""Sparse spelling and phrase cues, not a general detector of the letter d.

Positive cues are data compounds, standards, drafts, and short pieces of
industrial/structural words. Negative cues include d+ough and d+roid.
The boundary matters: ind+ust is a cue, ind+ustry is not. The unfinished
word is kept across tokens and reset at document boundaries. Unrecognized
contexts get zero; this leaves many real responses unexplained. There is
also a document-initial Title: cue and Chinese standard/data phrase cues.
"""
import re
from functools import lru_cache
from anyascii import anyascii
from opencc import OpenCC

READS = ()
SIMPLIFY = lru_cache(8192)(OpenCC('t2s').convert)
DATA_NOUNS = {
    'frame': 3.8,
    'structure': 3.3,
    'type': 1.4,
    'set': 1.4,
    'format': 0.9,
    'center': 1.3,
}
D_PIECES = {
    'ut': 2.4,
    'utt': 2.4,
    'uct': 2.4,
    'uc': 0.5,
    'ust': 1.2,
}

# Previous word's ending / current piece's beginning / response.
SPELLINGS = (
    (r'd$', r'^ough$', -5.8),                  # dough
    (r'dd$', r'^ard$', 5.5),
    (r'(?:d|u)$', r'^ard$', 1.7),
    (r'(?:str|struc)$', r'^(?:ut|ukt|uct)', 3.4),
    (r'(?:struk|strukt|strut|struct)$', r'^(?:tur|ure)', 2.0),
    (r'prod[u]?$', r'^(?:ut|utt|uk|k|kt)$', 3.4),  # product cognates
    (r'ind$', r'^ust$', 2.8),                 # industry cognates
    (r'indu$', r'^str$', 2.8),
    (r'indust$', r'^(?:ri|rie|ria|ry|rik)$', 2.8),
    (r'd$', r'^raft', 3.0),
    (r'dra$', r'^ught', 4.1),                 # draught
    (r'dr$', r'^uck', 1.5),
)


@lru_cache(8192)
def fold(text):
    return anyascii(text.lower())


def predict(s, previous, word, position):
    a, p, w = fold(s), fold(previous).strip(), fold(word)
    if position == 1 and previous == 'Title' and s == ':':
        return -4.49
    if 'dataframe' in s.lower():
        return 1.5 if s.startswith('.') else 2.25
    if p.endswith('data'):
        if a.startswith('.frame'):
            return 6.5
        for noun, value in DATA_NOUNS.items():
            if a.lstrip(' ._/').startswith(noun):
                return value
    if SIMPLIFY(s.strip()) == '标准':
        return 1.2
    if SIMPLIFY(previous).endswith(('数据', '资料')):
        if SIMPLIFY(s).startswith(('结构', '类型')):
            return 2.8
    attached = bool(a and a[0].isalpha() and w)
    combined = w + a if attached else a.strip()
    match = re.search(r'(?:standard|standart|estandar)', combined)
    if match and (not attached or match.end() > len(w)):
        if attached and w.endswith(('stand', 'estand', 'nd')):
            return 6.0 if s.isupper() else 4.3
        if 'standart' in a:
            return 2.9
        if p in ('safety', 'industry', 'international', 'national', 'funding'):
            return 2.2
        return 1.0 if a.rstrip().endswith('s') else 0.4
    if re.fullmatch(r'\s*drafts?', a):
        return 1.7
    if a.strip() in ('duty', 'duties', 'dut'):
        return 0.8
    if a.strip() == 'duct' and not attached:
