def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    first = prefix.position == 0 or (
        prefix.document_ids[-1] != prefix.document_ids[-2]
    )
    previous, word = ('', '') if first or carry is None else carry
    ending = re.search(r'[A-Za-z0-9]+$', word + text)
    next_word = ending.group()[-32:] if ending else ''
    state = (text, next_word)
    if first:
        if text.startswith('<|'):
            value = -0.05
        elif text.isdigit() or text.isspace():
            value = -0.78
        elif not any(c.isalnum() for c in text):
            value = -0.55
        else:
            value = -0.20
        return state, value
    if len(text) >= 2 and set(text) == {'·'} and previous == text:
        return state, -2.0
    match = re.fullmatch(r'([\W_]*)([sS][A-Za-z]*)', text)
    if not match:
        letter = text.strip()
        if len(letter) == 1 and anyascii(letter).lower() == 's':
            name = unicodedata.name(letter, '')
