    n = len(letters)
    cluster = not any(c in 'aeiou' for c in letters.lower())
    boundary = bool(lead) or not previous[-1:].isalpha()
    if letters[0].isupper() and previous[-1:].islower():
        boundary = True  # A camel-case beginning.
    if lead.endswith(("'", '’')) and previous[-1:].isalpha():
        boundary = False
    if lead == '.' and letters.isupper() and previous[-1:].isupper():
        boundary = False  # An initialism such as U.S.
    if not lead and letters == 's' and previous[-1:].isdigit():
        return state, -0.30 if word.isdigit() and len(word) >= 3 else -0.50
    if not boundary:
        if n == 1:
