        return state, -0.15 if cluster and n <= 3 else 0.03
    if n == 1:
        if lead and any(c in lead for c in '_/.-\t'):
            value = -1.05
        else:
            value = -0.95 if letters.isupper() else -0.78
    elif n <= 3:
        if letters.isupper():
            value = -0.38 if n == 2 else -0.20
        elif letters.lower() == 'str':
            value = -0.60  # The conventional abbreviation for string.
        elif cluster:
            value = -0.33 if n == 2 else -0.03
        else:
            value = -0.08 if n == 2 else -0.05
        if not lead:
            value *= 1.5
    else:
        value = -0.02
    return state, value

"""A context-initial pulse with an orthographic/word-familiarity scale.

It fires at row starts and packed-document resets, and continues through an
uninterrupted repetition of the first token. Otherwise it predicts zero.
Its scale uses script, case and English word frequency: unspaced title
case and very frequent English words get larger estimates. Digits,
punctuation, whitespace and Han text generally receive smaller pulses.
This is a coarse scale estimate, not a token-by-token activation lookup.
"""
import math
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

@lru_cache(maxsize=8192)
def initial_value(text):
    word = text.strip()
    if text.startswith('<|'):
        return 12.8
    if not word:
        if text == ' ':
            return 0.13
        if '\n' in text or '\t' in text:
            return 2.5
        if text == '\r':
            return -1.4
        return 6.0
    if word.isdecimal():
        return 7.9
    if all(unicodedata.category(c)[0] in 'PS' for c in word):
        if len(word) > 1 and len(set(word)) == 1:
            return 6.0 + 4.0 * math.log(len(word))
        return 4.6

    value = 10.3
    if word.isalpha():
        latin = all('LATIN' in unicodedata.name(c, '') for c in word)
        value += 5.8 if latin else 2.3
        if word.isascii():
            frequency = zipf_frequency(word.lower(), 'en')
            value += -0.63 * frequency + 2.85 * max(0, frequency - 4)
            spaced = text.startswith(' ')
            value += 1.1 * spaced
            if word.istitle() and len(word) > 1:
                value += 8.7 - 10.0 * spaced
            if word.isupper() and len(word) > 1:
                value -= 2.6
    if any('CJK' in unicodedata.name(c, '') for c in word):
        value -= 4.9
    return value


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        value = initial_value(prefix.token_strings[-1])
        return (doc, token, True, value), value
    doc, first_token, active, value = carry
    active = active and token == first_token
    return (doc, first_token, active, value), value if active else 0.0

