"""layers.1.mlp.down_proj:1257 -- a "first token of a document" detector.

This component is silent everywhere except on the first token of a document (position 0
of a row, or the first token after a document boundary, e.g. after <|endoftext|>). There
it fires strongly, and how strongly depends only on what that first token is:

- an ordinary capitalised word that opens a sentence ("The", "We", "When", "What") is high;
- other English words are medium;
- digits, special tokens and non-English text are lower;
- punctuation, whitespace and code-like symbols are lowest.

Mid-document tokens get 0. The value depends only on the token itself (at a document start
attention sees nothing else), so this is a small lookup from the token's surface form.
"""

import re

READS = ()

# Activation values for each kind of first token (typical values read off the model).
TIER = {
    "sentence_word": 25.0,  # capitalised word with no leading space: "The", "We", "When"
    "word": 17.0,  # other English word: " the", " of", " and"
    "letter": 13.0,  # a single letter
    "special": 13.0,  # <|im_start|> and other special tokens
    "non_ascii": 10.0,  # text in other scripts
    "code": 10.0,  # identifiers and code fragments mixed with punctuation
    "digit": 8.0,  # "1", "2", ...
    "punct": 4.5,  # punctuation and symbols
    "space": 2.0,  # whitespace and newlines
}

WORD = re.compile(r"[A-Za-z]+")


def first_token_kind(token: str) -> str:
    core = token.strip()
    if token.startswith("<|") and token.endswith("|>"):
        return "special"
    if core == "":
        return "space"
    if WORD.fullmatch(core):
        if len(core) == 1:
            return "letter"
        if not token.startswith(" ") and core[0].isupper():
            return "sentence_word"
        return "word"
    if core.isdigit():
        return "digit"
    if all(ord(c) < 128 for c in token):
        return "code" if any(c.isalpha() for c in token) else "punct"
    return "non_ascii"


def step(carry, prefix, upstream):
    t = prefix.position
    starts_document = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not starts_document:
        return carry, 0.0
    return carry, TIER[first_token_kind(prefix.token_strings[-1])]

