"""Sparse approximation of document-opening and formatting responses.

At the first token of a document, distinguish declaration-like code tokens,
imports, markup and heading markers. A colon immediately after the opening
'Title' is strongly negative. 'Questions' immediately after 'Similar' is
positive. Chat/tool delimiters get small signed values; everything else
stays near zero. Reset all state at document boundaries.

These rules capture selected spikes, not the component's broader lexical
variation: this version explains about 4% of held-out variance.
"""

READS = ()

# Source-code openings: declarations versus imports and interpreter directives.
CODE_OPENINGS = {
    'def': -2.82,
    'function': -1.75,
    'int': -2.07,
    'class': -0.95,
    'package': 0.57,
    'from': 0.92,
    'import': 0.31,
    '#include': 0.38,
    '#!/': 0.76,
    '<!': 1.31,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        _, position, previous = carry

    value = -0.0015
    if position == 0:
        if token in CODE_OPENINGS:
            value = CODE_OPENINGS[token]
        elif token == '#':
            value = 0.439
        elif token == 'Title':
            value = 0.598
        elif token == 'Question':
            value = -0.567
        elif token == '<|endoftext|>':
            value = 1.518
        elif token == '<|im_start|>':
            value = -0.128
    elif position == 1 and previous == 'Title' and token == ':':
        value = -2.804
    elif token == ' Questions' and previous.strip() == 'Similar':
        value = 0.80
    elif token == '<|im_end|>':
        value = -0.055
    elif token == '<tool_response>':
        value = 0.098
    elif token == '<tool_call>':
        value = 0.058

    return (doc, position + 1, token), value

"""Approximate a sequence-and-transition feature.

Narrative 'then', 'later', and multilingual after/then markers are negative;
nearby conditional clauses push 'then' in the positive direction. Recognize
next/following time periods and some spill into commas and pronouns. Case and
split-word spellings change the strength. Unmatched text returns zero.

These rules explain the strong event-order responses, not all small background
activations. Memory is a bounded byte suffix, reset at document boundaries.
"""
import re
import unicodedata
import inflect

READS = ()

# Common translations of temporal 'then', 'afterwards', and 'later'.
SEQUENCE = {
    'puis': -4.7, 'ensuite': -3.5, 'poi': -6.0,
    'luego': -4.5, 'después': -3.0, 'despues': -3.0,
    'depois': -4.5, 'dann': -3.0, 'danach': -3.0,
    'später': -2.4, 'lalu': -5.0, 'kemudian': -6.0,
    'затем': -7.5, 'потом': -3.3, 'далее': -4.5,
    'после': -2.2, 'спустя': -5.0, 'następnie': -5.2, 'sau': -3.0,
    'posterior': -2.5, 'successivo': -3.5, 'lendemain': -4.8,
    'dadurch': -4.0,
