"""Sequence words go negative: "then", "later", "next", "afterwards" and their translations are
strongly negative, as is a comma right after a transition adverb ("Meanwhile,", "Similarly,").
"Then" that closes an if-clause ("If ..., then") goes positive. Everything else is about zero."""

READS = ()

SEQUENCE = {  # time/sequence transition words -> typical activation
    "later": -2.0, "afterwards": -3.0, "subsequently": -2.5, "thereafter": -2.0,
    "sequently": -4.5, "dann": -3.0, "puis": -3.5, "sau": -3.0, "poi": -3.0, "alors": -1.0,
    "потом": -2.0, "после": -2.0, "然后": -4.0, "後": -2.0, "后": -0.7, "rồi": -1.7,
    "next": -0.6, "now": -0.5, "finally": -0.5, "after": -0.5,
    "morning": -1.0, "afternoon": -0.8, "night": -0.5,
}
TRANSITION = {"meanwhile", "similarly", "additionally", "furthermore", "addition", "also",
              "consequently", "finally", "now", "next", "later", "then", "instead", "contrast"}
CONDITION = {"if", "when", "whenever", "suppose", "assuming", "given", "unless", "once"}
SENTENCE_END = (".", "!", "?", "\n")

def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    prev = prev.strip().lower()
    if carry is None or prefix.document_ids[-1] != carry[1]:
        conditional = False  # has this sentence so far had an if-clause?
    else:
        conditional = carry[0]
    if word == "then":
        if prev in ("and", "but", "so", "") or prev.endswith(SENTENCE_END):
            value = -5.0  # "and then", "But then", sentence-initial "Then": sequence
        elif prev == "," and conditional:
            value = 4.0  # "If ..., then": the consequent of a condition
        elif conditional:
            value = 2.0
        else:
            value = -3.0  # "first ..., then ...", and other uses of time
    elif word == "," and prev in TRANSITION:
        value = -1.2  # the comma after a transition adverb
    else:
        value = SEQUENCE.get(word, 0.0)
    if word in CONDITION:
        conditional = True
    if any(c in word for c in SENTENCE_END):
        conditional = False
    return (conditional, prefix.document_ids[-1]), float(value)

