"""Approximate the component's spelling-sensitive activation tails.

BULK is strongly negative; BUL/ALK/ULK-related fragments are weaker
negatives, while MUL is positive. Case and combining accents are folded.
Only the current and preceding token fragments are joined. Spellings buried
inside whole tokens, or followed by long endings, are usually suppressed.
Document-initial 'Title:' and repeated middle dots have separate responses;
most other positions get zero.
"""
import re
import unicodedata

READS = ()

# Base strengths: (whole fragment, fragment spanning a token boundary).
# Order favors longer spellings over their substrings.
CLUSTERS = {
    'bulk': (-13.0, -13.0),
    'bulb': (-5.4, -6.0),
    'bulg': (-2.1, -5.0),
    'bull': (0.0, 0.0),
    'bult': (-2.4, -2.4),
    'bul': (-3.1, -3.4),
    'burk': (-2.7, -3.3),
    'buk': (-2.5, -4.7),
    'balk': (-3.8, -4.6),
    'alk': (-1.5, -4.5),
    'elk': (0.0, -1.0),
    'ulk': (-5.4, -7.0),
    'ulf': (-1.7, -4.5),
    'ult': (-0.4, 0.0),
    'luk': (-3.3, -2.3),
    'uk': (-0.5, -0.4),
    'kul': (-1.7, -2.5),
    'vul': (-0.9, -0.4),
    'mul': (2.9, 3.0),
    'ucl': (0.0, 2.7),
}


def cluster_response(root, mode, ending):
    """Suppress long lexical words, keeping short fragments and extensions."""
    if mode == 'embedded':
        return -0.8 if root == 'ulf' and not ending else 0.0
    if root == 'bulk':
        if not ending:
            return -13.0
        if ending in {'s', 'ed', 'ing'}:
            return -16.5
        return -8.5 if ending in {'y', 'ier', 'ley'} else 0.0
    if root == 'burk' and ending in {'e', 's', 'h'}:
        return -3.9
    if root == 'bulg':
        return -5.2 if mode == 'split' and len(ending) <= 3 else -1.5 if ending else -2.1
    if root == 'bulb' and ending:
        return -3.5 if len(ending) <= 2 else 0.0
    if root == 'bull':
        return -4.8 if mode == 'continued' and ending == 'ion' else 0.0
    if mode == 'continued':
        if root == 'ulk' and len(ending) <= 3:
            return -2.5
        if root == 'bul' and len(ending) <= 3:
            return -1.3
        if root == 'alk' and ending.startswith('al'):
            return -1.1
        return 0.0
    if not ending:
        return CLUSTERS[root][mode == 'split']
    if mode == 'inside':
        if root == 'alk' and ending in {'al', 'ali'}:
            return -1.0
        return 0.7 if root == 'mul' and ending == 'l' else 0.0
    # Spanning a boundary lets a short suffix retain the spelling signal.
    if root == 'ulk' and len(ending) <= 3:
        return -7.5 if ending == 'ing' else -5.5
    if root == 'mul' and len(ending) <= 2:
        return 4.0 if ending == 'e' else 2.0
    if root in {'bul', 'buk', 'ulf', 'kul', 'luk', 'uk'}:
        return CLUSTERS[root][1] * 0.5 if len(ending) <= 2 else 0.0
    if root == 'alk' and ending in {'y', 'an'}:
        return -3.8
    return 0.0


def spelling_response(previous, token):
    previous = ''.join(c for c in unicodedata.normalize('NFD', previous.lower())
                       if not unicodedata.combining(c))
    token = ''.join(c for c in unicodedata.normalize('NFD', token.lower())
                    if not unicodedata.combining(c))
    tail = re.search('[a-z]+$', previous)
    tail = tail[0][-16:] if tail else ''
    now = token.lower()
    joined = tail + now
    boundary = len(tail)
    for root in CLUSTERS:
        start = joined.rfind(root)
        if start < 0:
            continue
        end = start + len(root)
        if end <= boundary and (not now or not 'a' <= now[0] <= 'z'):
            continue
        ending = re.match('[a-z]*', joined[end:])[0]
        if end + len(ending) < boundary:
            continue
        if end <= boundary:
            mode = 'continued'
        elif start < boundary:
            mode = 'split'
        else:
            lead = re.search('[a-z]*$', joined[boundary:start])[0]
            mode = 'embedded' if lead else 'inside'
        return cluster_response(root, mode, ending)
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, position = '', 0
    if carry is not None and carry[0] == doc:
        _, previous, position = carry
    token = prefix.token_strings[-1]
    value = spelling_response(previous, token)
    if position == 1 and previous == 'Title' and token == ':':
        value = -8.67
    elif len(token) >= 2 and set(token) == {'·'}:
        value = -0.77
    elif previous.strip().lower().endswith('bulk') and token == ' of':
        value = -2.0
    return (doc, token, position + 1), float(value)

"""Approximate a bundle of date, number-five, and formatting responses.

Positive responses mark English month/day separators and ordinal endings,
GitHub domain endings, and repeated middle-dot leaders. Five depends on its
left context: Latin identifier letters or six strengthen it, while a decimal
point suppresses it. Related English number words have separate responses.
Identifier responses emphasize the more causally important training cases.
Two literal document-opening formats are also recognized. Everything else
predicts zero; state is only the current document's last 100 characters.
"""
import calendar
import re
from collections.abc import Mapping

READS = ()
_MONTH = '(?:' + '|'.join(
    list(calendar.month_name)[1:] + list(calendar.month_abbr)[1:] + ['Sept']
) + ')'
_DAY = r'(?:[0-2]?[0-9]|3[01])'
_MD = r'\b' + _MONTH + r'\.?\s+' + _DAY
_DATE = re.compile(_MD + r'$', re.I)
_COMMA_DATE = re.compile(_MD + r',$', re.I)
_ORDINAL_DATE = re.compile(_MD + r'(?:st|nd|rd|th)$', re.I)
_DAY_MONTH = re.compile(r'\b' + _DAY + r'(?:st|nd|rd|th)?\s+'
                        + _MONTH + r'\.?$', re.I)


def step(carry, prefix, upstream: Mapping):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = 0.0
    if token in (' ', " '", 'st', 'nd', 'rd', 'th', ','):
        if _DATE.search(before):
            if token == ',':
                value = 0.36
            elif token == ' ':
                value = 0.80
            elif token == " '":
                value = 1.13
            else:
                value = 1.39
        elif token == ' ':
            if _COMMA_DATE.search(before):
                value = 0.88
            elif _ORDINAL_DATE.search(before):
                value = 0.65
            elif _DAY_MONTH.search(before):
                value = 0.35
        elif token == ',' and _ORDINAL_DATE.search(before):
            value = 0.28
    if token == '.com':
        host = before.lower()
        if host.endswith('githubusercontent'):
            value = 1.93
        elif host.endswith('github') and not host.endswith('.github'):
            value = 1.80
        else:
            value = 0.05
    if token == '5':
        previous = before[-1:]
        if not previous:
            value = -0.116
        elif previous == '.':
            value = -0.17
        elif previous.isascii() and previous.isalpha():
            value = 0.87
        elif previous in '-/' and before[-2:-1].isascii() \
                and before[-2:-1].isalpha():
            value = 0.98
        elif previous == '6':
            value = 0.43
        elif previous.isdigit():
            value = 0.05
        elif previous == '_':
            value = 0.43
        elif previous.isspace():
            value = 0.20
        else:
            value = 0.10
    word = token.strip().lower()
    if word in ('five', '-five'):
        value = 0.60 if token.startswith('-') else 0.20
        if not token.startswith((' ', '-')):
            value = 0.48
        if before.lower().endswith('sixty'):
            value = 1.05
        elif before.lower().endswith('high'):
            value = 1.30
        if token.strip() == 'Five':
            value = 0.50
    if word in ('fifteen', 'fifth'):
        value = 0.35
    if word == 'fifty':
        value = -0.14
    if token == 'teen' and before.endswith('fif'):
        value = 1.10
    if token == 'teenth' and before.endswith('fif'):
        value = 1.78
    if token == 'ives' and before.endswith('high-f'):
        value = 4.0
    if token == '··' and (not before or before.endswith('·')):
        value = 1.62
    # Two distinctive document-opening formats, not general punctuation rules.
    if not before and token == ' .':
        value = 3.16
    elif before == 'Title' and token == ':':
        value = -1.70
    return (doc, (before + token)[-100:]), value

