"""layers.1.mlp.down_proj:1261 - a sparse "date and number" detector.

The component is nearly silent on ordinary text (typical size about 0.05). It fires on a
few recognisable spots, and the program predicts those spots:

1. ".com" right after "github" (as in "https://github.com/..."): strong, about 2.
2. A repeated middle-dot leader "··": about 1.6.
3. Dates written "Month day": the ordinal suffix ("th", "nd", "rd", "st") after
   the day, about 1.4; the comma after the day, about 0.4; and the space that
   starts the year after "Month day,", about 0.9. The space after any other
   comma is weakly positive, about 0.1.
4. The digit "5": it is most active after a letter (as in "hdf5", "perl5",
   "route53"), about 0.55; after "6" about 0.4; after a space about 0.2; after
   "/" about 0.3; after "." it is slightly negative. Other digits stay near 0.
5. Tokens containing "five" or "fif" ("five", "Five", "fifth", "fifteen"): about 0.3.

Everything else predicts 0. The program reads only the tokens so far and needs
no state across positions.
"""

READS = ()

# Month names, as they appear as whole tokens (with or without a leading space).
MONTHS = {"January", "February", "March", "April", "May", "June", "July", "August",
          "September", "October", "November", "December", "Jan", "Feb", "Mar", "Apr",
          "Jun", "Jul", "Aug", "Sep", "Sept", "Oct", "Nov", "Dec"}


def after_month_day(s, k):
    """True if the tokens up to index k end in "<Month> <day>", e.g. " May", " ", "1", "1".

    A day is one or two digit tokens, preceded by a space token."""
    digits = 0
    while k >= 0 and s[k].isdigit() and digits < 2:
        k -= 1
        digits += 1
    if digits == 0 or k < 0 or s[k] != " ":
        return False
    return k >= 1 and s[k - 1].strip() in MONTHS


def step(carry, prefix, upstream):
    s = prefix.token_strings  # tokens 0..t, each decoded alone
    t = s[-1]                 # the current token
    p1 = s[-2] if len(s) > 1 else ""  # the token before it

    if t == "··":
        v = 1.6
    elif t == ".com" and p1 == "github":
        v = 2.0
    elif t in ("th", "st", "nd", "rd") and after_month_day(s, len(s) - 2):
        v = 1.4
    elif t == " " and p1 == "," and after_month_day(s, len(s) - 3):
        v = 0.9
    elif t == " " and p1 == ",":
        v = 0.1
    elif t == "," and after_month_day(s, len(s) - 2):
        v = 0.4
    elif t == "5":
        if p1[-1:].isalpha():
            v = 0.55
        elif p1 == "6":
            v = 0.43
        elif p1 == " ":
            v = 0.2
        elif p1 == "/":
            v = 0.3
        elif p1 == ".":
            v = -0.15
        else:
            v = 0.07
    elif "five" in t.lower() or "fif" in t.lower():
        v = 0.3
    else:
        v = 0.0
    return None, float(v)

programs.sol:
"""A short look-behind detector, chiefly for material immediately after #.

Numeric character references and hexadecimal colors give the largest negative
responses; numbered labels and attached identifiers give smaller ones. Whitespace
breaks that response. There is a short tail into a second digit. Separate positive
responses follow Japanese お. Two byte-prefix rules cover private-use characters
and split emoji. Everything else is approximated by zero.
"""
import re
import unicodedata

READS = ()
DIRECTIVES = set(
    "include define if ifdef ifndef endif else elif pragma error line undef".split()
)


def activation(previous, current, before, tail):
    s = current.decode('utf-8', 'replace')
    p = previous.decode('utf-8', 'replace')
    # EE begins UTF-8 private-use characters U+E000 through U+EFFF.
    if previous == b'\xee' and current and 128 <= current[0] < 192:
        return -3.2 if len(current) == 1 else 0.0
    # A token ending midway through a space-prefixed emoji.
    if previous.endswith(b'\xf0\x9f') and previous.startswith(b' '):
        return -1.8
    # Exclude the connective なお rather than treating it as honorific お.
    if p.endswith('お') and p != 'なお':
        name = unicodedata.name(s[0], '') if s else ''
        if 'HIRAGANA' in name or 'KATAKANA' in name:
            return 4.1
        if s and (s[0].isalpha() or s[0] == '\ufffd'):
            return 4.3 if len(s) == 1 and s != '\ufffd' else 0.8
    if p.endswith('#'):
        if re.search(r'\$\(\s*[\"\x27]#$', tail):
            return 0.0
        if s.startswith('>') or s.lstrip().startswith('=>'):
            return 2.2
        if not s or s[0].isspace():
            return 0.8 if s.isspace() and p == ' #' else 0.0
        if tail.endswith('&#'):
            return -9.6 if p.startswith(' ') else -11.7
        if s.isascii() and all(c in '0123456789abcdefABCDEF' for c in s):
            color = re.search(r'(?:[:=]\s*[\"\x27]?|[\"\x27])#$', tail)
            if color:
                return -11.0 if len(s) == 1 else -8.0
        if p.endswith('##'):
            return -2.0 if s.isalnum() else 0.0
        if s.isascii() and s.isdigit():
            if tail.endswith('(#') or s == '0':
                return -5.7
            return -4.8 if p.startswith(' ') else -5.5
        if s.isascii() and s.isalpha():
            if tail.endswith('{#'):
                return -4.7
            if tail.endswith('(#'):
                return -5.1 if len(s) == 1 else -1.6
            if len(s) == 1:
                if s.islower() and p.startswith(' '):
                    return -2.5
                return -4.3
            if s.lower() in DIRECTIVES:
                return 0.0
            if len(s) <= 3:
                return -1.2
            return -0.3
        return 0.0
    if before.endswith(b'#') and previous.isdigit() and current.isdigit():
        if before.endswith(b'&#'):
            if current == b'4':
                return -1.7
            return 0.0
        if current == b'0':
            return -2.5
        return -1.5
    if (tail.endswith('&#x') and current
            and current[0] in b'0123456789abcdefABCDEF'):
        return -3.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, b'', b'', '')
    _, previous, before, tail = carry
    current = prefix.token_bytes[-1]
    value = activation(previous, current, before, tail)
    tail = (tail + current.decode('utf-8', 'replace'))[-100:]
    return (doc, current, previous, tail), value

"""A spelling-fragment detector for jak/jack/jay, yak and kak families.

These give negative writes, especially Jackson, Russian как, and Korean -야.
Fragments with a liquid consonant before 'ak' give positive writes instead.
The preceding token completes split syllables; short vowel endings retain a
little of the preceding write. This is a spelling rule, not a semantic test.
"""
import re
from functools import lru_cache
from anyascii import anyascii

READS = ()


@lru_cache(maxsize=8192)
def roman(text):
    return anyascii(text).lower()


def fragment(text, previous):
    s = roman(text)
    word = s.strip(' ._')
    raw = text.strip().lower()
    attached = bool(text and text[0].isalpha())
    # Capitalized fragments can begin a new word inside a camelCase name.
    if text[:1].isupper() and previous[-1:].isupper():
        if any(c.islower() for c in previous):
            attached = False
    p = roman(previous) if attached else ''
    last = p[-1:]

    if raw.endswith('야'):
        return -7.4 if len(raw) == 1 else -6.2
    if raw == 'ак' and not attached:
        return 1.8
    if raw == 'как':
        # In the conjunction 'так как' ('because'), the response disappears.
        return 0.0 if previous.strip().lower() == 'так' else -5.5
    if raw.startswith('как'):
        return -3.2
    if raw == 'никак':
        return -2.7
    if word == 'jackson':
        return -7.5
    if word.startswith('jackson'):
        return -1.0
    if word.startswith('jacket'):
        return -1.8 if word == 'jacket' else -1.3
    if word in ('jack', 'jay'):
        return -4.0
    if word == 'ajax':
        return -2.7
    if word in ('jak', 'yak', 'kay', 'kak'):
        if word == 'jak':
            return -4.8 if attached else -3.8
        return -3.2
    if word.startswith(('jak', 'yak', 'kay', 'kak')):
        return -1.4 if len(word) == 4 else -0.6
    if word == 'jac':
        return -1.4

    # Do not confuse long-vowel Latin spellings (ák, äk) with plain ak.
    if s.startswith(('ak', 'ac', 'ax', 'ay')) and attached:
        if raw[0] not in 'aаα':
            return 0.0

    # Palatal/glide or velar onsets, split from the following a-syllable.
    if last in ('j', 'y', 'k') and s.startswith(('ak', 'ack', 'ax', 'ay', 'ac')):
        if s.startswith('ackson'):
            return -9.0
        if s.startswith('ak') and p.endswith(('ay', 'aj')):
            return (-10.5 if text.isupper() else -8.5) if len(s) == 2 else -5.5
        if s.startswith('ack'):
            if s.startswith('acket'):
                return -3.4
            return -5.2 if s == 'acks' else -6.4
        if s.startswith('ax'):
            return -8.3 if last == 'j' else -5.5
        if s.startswith('ak'):
            base = 6.0 if last == 'j' else 3.6 if last == 'y' else 2.9
            if raw.startswith('ак') and last == 'k':
                base = 6.1
            return -base if len(s) == 2 else -0.6 * base
        if s.startswith('ay'):
            base = 7.1 if last == 'j' else 3.5 if last == 'k' else 2.7
            return -base if len(s) == 2 else -0.6 * base
        return (-2.4 if last == 'j' else -1.1) if len(s) <= 4 else 0.0

    # A consonant supplied after an a/ya syllable in the previous token.
    if re.match(r'^(?:k(?!h)|ch)', s) and p.strip() in ('ya', 'ka', 'ra', 'la'):
        if p.endswith('ya'):
            base = -5.0 if previous.strip().lower() in ('я', 'ya') else -0.8
        else:
            base = -2.8 if p.endswith('ka') else 2.3
        return base if len(s) <= 2 else base * 0.55

    # Liquid + ak is the opposite-polarity family: rak/lak, prak/plak, etc.
    if raw == 'рак':
        return 4.7
    if word in ('rak', 'lak', 'trak'):
        return 2.5
    if s.startswith(('ak', 'ack', 'ax')):
        if last in ('r', 'l'):
            base = 2.0 if last == 'r' else 2.6
            if len(p) >= 2 and p[-2] in 'bpvt':
                base += 2.4
            if raw.startswith('ак'):
                base *= 1.7
            if s.startswith('ack'):
                base *= 0.5
            # Long/silent-e fragments, such as flake, are not the ak syllable.
            if s.startswith(('ake', 'akh', 'aky')) or len(s) > 3:
                base *= 0.1
            return base
        if raw.startswith('ак'):
            return 1.8 if not p else 0.8
        if last == 'z':
            return 1.0
    if s == 'arak':
        return 1.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, old_value = '', 0.0
    else:
        _, previous, old_value = carry
    text = prefix.token_strings[-1]
    value = fragment(text, previous)
    if value == 0.0 and re.fullmatch(r'(?:[aeiouy]|ie|oe)', roman(text)):
        value = 0.4 * old_value
    return (doc, text, value), float(value)

