"""layers.1.mlp.down_proj:1263 -- a word-spelling detector, mostly negative.

What it does: the component is silent on most text, but it reacts strongly to a few
word-pieces.
  * Russian "как" (as / like / how), and its relatives никак, какой, какие: strongly
    negative (about -5). The exception is "так как" (since), which stays near zero.
  * English name/word pieces Jack, Jackson, Jax, Jak, Jay, Kay, kayak, yak: strongly
    negative (about -5).
  * Korean 야 / 해야 / 어야 (the "-ya" of Korean verb endings): negative (about -7).
  * Cyrillic рак, lak, rax (crab, "lak"-type pieces): positive (about +3.5).
  * Cyrillic ак: weakly positive (+0.8); Latin ak / ax: weakly positive (+0.25).
  * Latin ay / aya / aye: weakly negative (-0.4).
Everything else predicts 0. The program is stateless: it only looks at the current
token and the one before it (for "так как").

Why: these are the pieces that carry most of the component's variance. Its contribution
is large and sign-definite on them, so a short lexicon with group means explains about
a third of the variance. The rest is mostly context-dependent sign flips on "ak", "ay"
and "к", which a word list cannot capture.
"""

READS = ()

# Russian "как" (as/like/how) and forms built on it.
RU_KAK = {"как", "никак", "какой", "какие", "какая", "какое", "каких", "каком", "какими"}
# English names and words built from J/K + "ak/ay/ax" spellings.
J_NAMES = {"jack", "jackson", "ackson", "jax", "jak", "jay", "kay", "kayak", "yak"}
# Korean 야 and the verb endings 해야, 어야.
KOREAN_YA = {"야", "해야", "어야"}
# Cyrillic and Latin pieces that come out positive.
RAK_LIKE = {"рак", "lak", "rax"}
CYR_AK = {"ак"}
LATIN_AK = {"ak", "ax"}
AY = {"ay", "aya", "ayar", "aye"}


def value(tok: str, prev: str) -> float:
    """The component's activation at a token, given the token and the one before it."""
    s = tok.strip().lower()
    if s in RU_KAK:
        return 0.0 if prev.strip().lower() == "так" else -5.0
    if s in J_NAMES:
        return -5.0
    if s in KOREAN_YA:
        return -7.0
    if s in RAK_LIKE:
        return 3.5
    if s in CYR_AK:
        return 0.8
    if s in LATIN_AK:
        return 0.25
    if s in AY:
        return -0.4
    return 0.0


def step(carry, prefix, upstream):
    """Called once per token. Stateless: reads the newest token and the one before it."""
    toks = prefix.token_strings
    prev = toks[-2] if len(toks) > 1 else ""
    return None, float(value(toks[-1], prev))

programs.sol:
"""Fractions and named roots, plus a few orthographic side responses.

Denominator openings in LaTeX fractions and 'square/cube/... root' are
positive. It also models usually negative responses to Greek kappa/theta,
Chu/Chuck spellings, and github.com.
A tiny brace parser distinguishes fractions from templates and code.
"""
import re
import unicodedata

READS = ()
ROOT_DEGREE = re.compile(
    r'(?:\b(?:square|cube|cubic|third|fourth|fifth|sixth|nth)'
    r'|\b\d+(?:st|nd|rd|th))[-_ ]*$', re.I)


def fraction_braces(text, command, depth, waiting):
    """Approximate TeX arguments; waiting stores (brace depth, argument number)."""
    denominator = False
    waiting = list(waiting)
    for ch in text:
        if command is not None:
            if ch.isascii() and ch.isalpha():
                command += ch
                continue
            if command in ('frac', 'dfrac', 'tfrac', 'cfrac'):
                waiting.append((depth, 0))
            elif command and waiting and waiting[-1][0] == depth:
                base, stage = waiting.pop()
                if stage == 0:
                    waiting.append((base, 1))
            command = None
        if ch == '\\':
            command = ''
        elif ch == '{':
            if waiting and waiting[-1][0] == depth:
                base, stage = waiting.pop()
                if stage == 0:
                    waiting.append((base, 1))
                else:
                    denominator = True
            depth += 1
        elif ch == '}':
            depth = max(0, depth - 1)
            waiting = [w for w in waiting if w[0] <= depth]
        elif ch == '$':
            waiting = []
        elif not ch.isspace() and waiting and waiting[-1][0] == depth:
            base, stage = waiting.pop()
            if stage == 0:
                waiting.append((base, 1))
    return denominator, command, depth, tuple(waiting)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before, command, depth, waiting = b'', None, 0, ()
    else:
        _, before, command, depth, waiting = carry
    token = prefix.token_strings[-1]
    past = before.decode('utf8', 'ignore')
    word = token.strip().lower()
    denom, command, depth, waiting = fraction_braces(
        token, command, depth, waiting)
    value = 0.0
    if token in ('}{', '}{\\'):
        value = 3.15 if denom else 1.0
    elif token in ('{', '{{', '{\\', '{(', ' {', ' {\\') and denom:
        # Separately tokenized denominator braces have the largest response.
        value = (5.7 if token.startswith(' ') else 8.0)
        if not past.rstrip().endswith('}'):
            value = 3.0  # an unbraced numerator
    elif word == 'frac' and (past.endswith('\\') or
                             command in ('dfrac', 'tfrac', 'cfrac')):
        value = 0.66
    elif token == '\\' and past.endswith('}{'):
        value = 1.25
    elif token == '}}':
        value = 0.29
    elif token == '){':
        value = 0.4
    elif token == ']{':
        value = 0.9
    elif token == ')/(':
        value = 0.37
    elif token == '/(':
        value = 0.18
    elif word.lstrip('-_') in ('root', 'roots'):
        if ROOT_DEGREE.search(past):
            value = 8.3 if word.endswith('s') else 6.5
        else:
            value = -0.45 if token.startswith(' ') else -0.15
    elif word == 'by':
        if re.search(r'\b(divide|divided|dividing)\s*$', past, re.I):
            value = 0.65
    elif token == '.com' and past.lower().endswith('github'):
        value = -1.3
    elif word in ('κ', 'θ'):
        letters = unicodedata.normalize('NFD', past.rstrip())
        letters = ''.join(c for c in letters if not unicodedata.combining(c))
        last = letters[-1:].lower()
        if word == 'κ':
            if token.startswith(' '):
                value = -2.85
            elif last == 'ι':
                value = 0.4
            elif last == 'η':
                value = -7.6
            elif last and '\u0370' <= last <= '\u03ff':
                value = -5.9 if last == 'ρ' else -4.0
            if token.strip() == 'Κ':
                value *= 0.65
        elif last and '\u0370' <= last <= '\u03ff':
            value = (0.0 if last == 'ι' else
                     -1.6 if last in 'αεο' else
                     -6.0 if last in 'ηω' else
                     -2.8 if last == 'υ' else -4.2)
    elif token == '楚':  # Chu: the Chinese name and historical state
        value = -5.0
    elif word == 'chuck':
        value = -4.8 if token.startswith(' ') else -2.9
    elif token in ('uk', 'uck') and past.lower().endswith('ch'):
        value = -7.2 if word == 'uck' else -4.7
    elif word == 'chu':
        value = -4.6 if past.lower().endswith('ch') else -1.5
    return (doc, (before + prefix.token_bytes[-1])[-100:],
            command, depth, waiting), value

programs.haiku:
"""Fires on LaTeX fraction denominators, and on "root" in "square root" / "cube root".

Main idea. In LaTeX a fraction is written \\frac{numerator}{denominator}. The component
fires most strongly on the brace that opens the denominator, right after the numerator's
closing brace (e.g. the "{" in \\frac{\\sqrt{3}}{2}). When the brace pair is written as one
token "}{", it fires more weakly. The bare command "frac" fires a little.

It also fires on "root" after "square" or "cube". It is negative on the Greek letters
kappa and theta inside Greek words (not after iota), and on the name fragment "Chu"
(楚, Chuck). Everything else is about zero.

A brace counter tracks the numerator of each \\frac; all other rules look only at the
current and previous token.
"""
import unicodedata

READS = ()


def is_greek_letter(s):
    return len(s) > 0 and unicodedata.name(s[-1], "").startswith("GREEK")


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    prev = toks[-2] if len(toks) > 1 else ""
    new_row = len(toks) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    # State: brace depth; depth of the open numerator (-1 if none); waiting for the
    # numerator's "{" after "frac"; whether a numerator has just closed.
    if new_row or carry is None:
        depth, numer, waiting, closed = 0, -1, False, False
    else:
        depth, numer, waiting, closed = carry

    # Value of this token, given the state before it.
    if cur.startswith("{") and closed:
        value = 8.2  # opens a \frac denominator
    elif cur == "}{":
        # closes a numerator and opens the denominator in one token
        value = 3.1 if numer != -1 and depth == numer else 0.9
    elif cur.endswith("frac"):
        value = 0.65
    elif cur in (" root", " roots") and prev in (" square", " cube"):
        value = 6.5
    elif cur.strip() in ("κ", "θ", "Κ") and is_greek_letter(prev) and not prev.endswith("ι"):
        value = -3.0
    elif cur in ("楚", "chu", "Chuck", " chuck"):
        value = -5.0
    elif cur == ".com" and prev == "github":
        value = -1.3
    else:
        value = 0.0

    # Update the brace state with this token.
    closed = False
    if cur.endswith("frac"):
        waiting = True
    for ch in cur:
        if ch == "{":
            depth += 1
            if waiting:
                numer, waiting = depth, False
        elif ch == "}":
            depth -= 1
            if numer != -1 and depth < numer:
                numer, closed = -1, True
    return (depth, numer, waiting, closed), value

programs.sol:
"""Approximate English compound-phrase responses, using two adjacent tokens.

Compass-qualified places and selected origin/content/value/record compounds
receive negative values. Ordering, geometry, relationships and selected technical
phrases receive positive values. Unmatched positions receive zero.
This is a partial lexical explanation, not a general semantic classifier;
it misses many individual compounds and the component's non-English uses.
"""
import re
from functools import lru_cache
import inflect
import pycountry
import wordnet

READS = ()

DIRECTIONS = set('''north south east west
northern southern eastern western'''.split())
COUNTRIES = {c.name.split(',')[0].lower() for c in pycountry.countries}
US_STATES = {
    s.name.lower() for s in pycountry.subdivisions if s.country_code == 'US'
}
CONTINENT_WORDS = set('''africa african america american asia asian
europe european oceania antarctica'''.split())
NON_PLACE_HEADS = set('''road street gate side edge shore line boundary front
 district hemisphere territory division league railway railroad high main
 central coast'''.split())
_engine = inflect.engine()
ORDINALS = {_engine.number_to_words(_engine.ordinal(i)) for i in range(1, 11)}


@lru_cache(maxsize=1024)
def is_place(word):
    return 'noun.location' in wordnet.categories(word)


def compound(previous, token):
    p = previous.strip().lower()
    w = token.strip().lower().lstrip('_-.')
    if not p or not w:
        return 0.0
    if p == '<|endoftext|>' and w in {'the', 'a', 'an'}:
        return -0.5

    # Compass modifiers: countries, states, other places, and boundaries.
    if p in DIRECTIONS:
        if w == 'central':
            return -2.4
        if w in {'east', 'west'}:
            return 0.4
        if w in {'gate', 'side', 'edge', 'shore', 'road', 'street'}:
            return 0.8
        proper_head = token[:1].isspace() and token.strip()[:1].isupper()
        if proper_head and w not in NON_PLACE_HEADS and len(w) > 3:
            if w in US_STATES:
                return -2.0
            if w in COUNTRIES or w in CONTINENT_WORDS:
                return -0.6
            return -1.4 if is_place(w) else -0.2

    # Ordering, geometric relationships, and a financial formula's name.
    if p == 'black' and token.lower().startswith('-s'):
        return 3.5  # Beginning of Black-Scholes.
    if w in {'order', 'orders'}:
        if p in ORDINALS or re.fullmatch(r'\d*(?:st|nd|rd|th)', p):
            return 1.5
        if p in {'natural', 'normal', 'higher', 'lower', 'high', 'low',
                 'partial', 'total', 'lexicographic', 'national', 'grand',
                 'special', 'liberal'}:
            return 1.5
    # Major/semimajor and transverse may themselves be split into pieces.
    if w == 'axis' and p.endswith(('ajor', 'minor', 'verse')):
        return 3.0
    if w == 'ratio' and p in {'common', 'golden'}:
        return 2.4
    if w in {'relation', 'relations'} and p in {'international', 'public'}:
        return 2.7
    if w in {'product', 'products'} and p in {'natural', 'national', 'special'}:
        return 3.0
    if p == 'public' and w in {'license', 'debt', 'goods'}:
        return 2.5

    # Qualified origins, information fields, quantities, and public records.
    if w in {'origin', 'origins'} and p in {'of', 'national'}:
        return -5.5 if p == 'national' else -1.5
    if w == 'contents' and p == 'of':
        return -2.8
    if w in {'content', 'contents'} and p in {
        'full', 'web', 'left', 'right', 'max', 'min', 'missing',
        'invalid', 'inline', 'android'
    }:
        return -2.0
    if w in {'value', 'values'} and p in {
        'national', 'global', 'market', 'shared', 'aesthetic',
        'core', 'single', 'static', 'extreme'
    }:
        return -3.0 if p in {'national', 'global'} else -1.5
    if w in {'security', 'interest', 'interests', 'record', 'records',
             'register', 'average', 'capital'} and p in {
        'national', 'public', 'world', 'social', 'homeland'
    }:
        return -1.7
    if w.startswith('champion') and p in {'world', 'national'}:
        return -2.4

    return 0.0


def step(carry, prefix, upstream):
    if (prefix.position == 0
            or prefix.document_ids[-1] != prefix.document_ids[-2]):
        return None, 0.0
    return None, compound(prefix.token_strings[-2], prefix.token_strings[-1])

"""An initial-context pulse, with its strength estimated from token type.

Emit a negative value at a document's first token (including a row cut in the
middle of a sentence), and keep emitting it while that same token repeats.
Once a different token arrives, predict a near-zero background. The pulse is
weaker on separators and numbers than on ordinary words. Common English
words after a space get a reduced pulse; indefinite articles are an exception.
This averages over token-specific amplitudes and omits rare later spikes.
"""
from wordfreq import zipf_frequency

READS = ()


def initial_strength(s):
    word = s.strip()
    lower = word.lower()
    if s.startswith('<|'):
        return -2.75
    if not word:
        if '\t' in s:
            return -4.5
        if '\n' in s:
            return -0.4 if s.count('\n') >= 2 else -1.25
        return -1.12 if len(s) == 1 else -2.5
    if word.isdecimal():
        return -2.3
    if word in {',', '，'}:
        return -0.65
    if word == '.':
        return -1.5
    if word == '#':
        return -4.9
    if word in {'(', ')', ':', '=', ']', '}'}:
        return -1.1
    if lower in {'a', 'an'}:
        return -5.5
    if lower in {'import', 'using', 'package'}:
        return -6.2
    if word.isascii() and word.isalpha():
        common = zipf_frequency(lower, 'en') >= 5.0
        if common and s.startswith(' '):
            return -2.9
        if not common and lower.endswith('s'):
            return -5.3
        if lower.endswith(('ed', 'ing')):
            return -4.9
        return -4.3
    return -3.0 if any(c.isalpha() for c in word) else -2.7


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_bytes[-1]
    if carry is None or carry[0] != doc:
        value = initial_strength(prefix.token_strings[-1])
        return (doc, token, value), value
    if carry[1] == token:
        return carry, carry[2]
    # None marks that the initial same-token run has ended.
    return (doc, None, 0.002), 0.002

"""Mostly a lexical detector for 各 ('each') and its Sino-Korean/Vietnamese forms.

Isolated 各 is strongest, weaker in Japanese and in fused compounds. There
are smaller responses to some similar syllables and to initial formatting.
This is not a detector for every expression meaning 'each'. UTF-8 fragments
are joined before matching; document boundaries reset all state.
"""
import codecs
import regex
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, codecs.getincrementaldecoder('utf-8')('ignore'), '', True)
    doc, decoder, recent, initial = carry
    raw = prefix.token_bytes[-1]
    text = decoder.decode(raw)
    word = text.strip()
    value = 0.0

    if word == '各':
        japanese = regex.search(r'[\p{Hiragana}\p{Katakana}]', recent)
        value = 5.2 if japanese else 9.4
        if raw != text.encode('utf-8'):
            value += 2.0
    elif word.startswith('各'):
        # Countable individuals/items versus more lexicalized compounds.
        if word[1:] in ('个', '個', '项', '項'):
            value = 3.0
        elif len(word) > 2 or word[1:] in ('地', '自', '位', '界'):
            value = 0.3
        else:
            value = 1.2
    elif word.casefold() == 'các':
        value = 4.3
    elif word == 'ác' and recent.endswith(('C', 'c')):
        value = 8.0
    elif word.casefold() == 'cá':
        value = 2.5
    elif word.casefold() == 'cách':
        value = 1.9 if word[0].isupper() else 0.5
    elif word == 'ách' and recent.endswith(('C', 'c')):
        value = 2.5
    elif word == 'án' and recent.endswith(('g', 'G')):
        value = 3.3  # Completing Vietnamese gán, 'assign'.
    elif word == '각':
        if text[:1].isspace():
            value = 3.5
        elif recent.endswith(('시', '심', '생')):
            value = 0.4  # 시각/심각/생각 are not the quantifier.
        elif recent.endswith('감'):
            value = 1.0  # Part of 감각, 'sense'.
        elif regex.search(r'(^|[^\p{Hangul}]|제|각)$', recent):
            value = 3.8
        else:
            value = 2.3
    elif word == 'ッ':
        value = 0.87
    elif word == '··':
        value = 1.14

    # A vowel continuing a word-initial Greek kappa (ka/ke syllables).
    if regex.search(r'(^|\W)[κΚ]$', recent):
        base = unicodedata.normalize('NFD', word)
        if base in ('α', 'ε'):
            value = 0.9
        elif base in ('α\u0301', 'ε\u0301'):
            value = 2.1 if base[0] == 'α' else 1.2

    if initial:
        if text == '<|endoftext|>':
            value = 3.26
        elif text == '\t':
            value = 1.93
        elif text == '\\t':
            value = 2.92
        elif text in ('\\n', '\\"'):
            value = 1.95
        elif text == '\r':
            value = 2.08
    initial = initial and text in ('\t', '\\t', '\r', '')
    return (doc, decoder, (recent + text)[-80:], initial), value

programs.haiku:
"""Layer-1 MLP down-projection, component 1269: a sparse lexical detector.

What it does, in plain terms (checked on ~20k training rows):
- Strongest and most consistent: the Chinese word 宅 (home, as in 自宅 / 宅), and
  住宅 (residence), 别墅 (villa), 住房 (housing). Activation about 1.5 to 5.
- A few specific characters that also fire strongly: 桑, 桃, 桐, 桩. There is no
  shared concept behind this list; it is kept because the activations are large and
  consistent.
- LaTeX shape/symbol macro names right after a backslash: \\square, \\Box, \\boxed,
  \\emptyset ("empty"), \\star, \\bullet, \\dots, \\top, \\bot, and the "var" piece of
  \\varphi. Activation about 2.
- Geometric shape symbols (□ ■ ◇ ◊ ▽ △ ...): a weak positive, about 0.5.
- Runs of a repeated filler token: the second and later copies of the dot leader
  '··' push it strongly negative, and so does the box-drawing bar '⎯'.
- Everything else is 0. Most of the variance is not captured by any of these
  groups: the component's activation is spread over many tokens with small values.

The program keeps one number of state, the length of the current run of identical
tokens within a document, and resets it at each document start.
"""

READS = ()

HOUSE = {"宅": 5.0, "住宅": 3.4, "住房": 1.0, "别墅": 0.6}
TREE_LIKE = {"桑": 3.0, "桃": 3.0, "桐": 3.0, "桩": 3.0}
SHAPES = set("□■◇◊▽△▼▲◆★☆♤♡♧♦♥◯○●▶✖⊥▓")
MACROS = {
    "Box", "box", "boxed", "square", "Square", "sq", "squ", "empty", "star",
    "bullet", "dots", "top", "bot", "bottom", "var",
}
FILLER = {"··": -2.5, "⎯": -1.7}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    t = prefix.position
    same_doc = t > 0 and prefix.document_ids[-2] == prefix.document_ids[-1]
    if t > 0 and same_doc and prefix.token_ids[-2] == prefix.token_ids[-1]:
        run = (carry or 1) + 1
    else:
        run = 1

    if token in FILLER and run >= 2:
        value = FILLER[token]
    elif token in HOUSE:
        value = HOUSE[token]
    elif token in TREE_LIKE:
        value = TREE_LIKE[token]
    elif token in SHAPES:
        value = 0.5
    elif token in MACROS and t > 0 and prefix.token_strings[-2].endswith("\\"):
        value = 2.0
    else:
        value = 0.0
    return run, float(value)

programs.sol:
"""Approximate a chat-framing component with readable text rules.

Tool boundaries and user headers get large negative values, while opening
a thinking block is positive.  Document-initial headers are weaker.
The previous message's ending punctuation modestly changes the boundary
response.  Plain mentions of users get a smaller negative value; other
ordinary text is left at zero, ignoring its word-specific fluctuations.
"""
READS = ()


def boundary_value(ending, start):
    """A message boundary depends on how the preceding message ended."""
    if ending == '</tool_call>':
        return -0.72 if start else 0.30
    if ending == '</tool_response>':
        return -0.88 if start else 0.15
    if ending.rstrip().endswith(('.', '。')):
        return -1.33 if start else -0.20
    if ending.rstrip().endswith(('?', '？')):
        return -1.09 if start else -0.10
    return -0.98 if start else -0.02


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, recent = 0, ()
    else:
        _, position, recent = carry
    token = prefix.token_strings[-1]
    previous = recent[-1] if recent else ''
    value = 0.0
    if token == '<tool_call>':
        at_header = recent[-2:] == ('assistant', '\n')
        value = -0.79 if position == 0 else (-3.25 if at_header else -3.49)
    elif token == '</tool_call>':
        value = -0.48 if position == 0 else -2.45
    elif token == '<tool_response>':
        value = -2.02
    elif token == '<think>':
        value = 1.20
    elif token == '<|im_start|>':
        ending = recent[-3] if len(recent) >= 3 else ''
        value = -0.52 if position == 0 else boundary_value(ending, True)
    elif token == '<|im_end|>':
        value = boundary_value(previous, False)
    elif token == 'user' and previous == '<|im_start|>':
        value = -0.735 if position == 1 else (-1.63 if position < 9 else -2.39)
    elif token == 'assistant' and previous == '<|im_start|>':
        value = -0.58 if position < 32 else -0.41
        if '</tool_response>' in recent:
            value += 0.12
    elif token.strip().lower() in ('user', 'users'):
        value = -0.23
    return (doc, position + 1, (recent + (token,))[-5:]), value

"""A spelling-sensitive signal for Latin comparative and relative-order words.

Whole words such as inferior, posterior and senior have distinct strengths.
Short ior/yor fragments respond more broadly, including across a token
boundary. Most other tokens produce zero. The carry is the last token,
reset at document boundaries. French and Cyrillic fragments and a few
related vowel transitions are included; this is an approximation, not a
semantic ranking parser.
"""
import re
import unicodedata
from functools import lru_cache

READS = ()
COMPARATIVES = {
    'inferior': 10.0, 'superior': 7.5, 'posterior': 10.2,
    'anterior': 6.1, 'interior': 4.4, 'exterior': 4.5,
    'ulterior': 6.0, 'senior': 2.9, 'junior': 2.7,
    'prior': 1.2, 'deterior': 1.9,
}
ORDER_WORDS = {
    'subordinate': 3.7, 'superintendent': 1.5,
    'subsequent': 0.8, 'subsequently': 0.7, 'successor': 0.9,
    'intermediate': 0.5, 'preceding': -1.1,
}

@lru_cache(maxsize=8192)
def plain(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text.lower())
                   if unicodedata.category(c) != 'Mn')


def response(previous, text):
    s = plain(text)
    token = s.strip()
    if token in COMPARATIVES:
        return COMPARATIVES[token]
    if token.endswith('s') and token[:-1] in COMPARATIVES:
        return 0.7 * COMPARATIVES[token[:-1]]
    if token.endswith('ity') and token[:-3] in COMPARATIVES:
        return 0.35 * COMPARATIVES[token[:-3]]
    if token in ORDER_WORDS:
        return ORDER_WORDS[token]
    # A short Latin suffix can fire even in an unrelated name or spelling.
    if re.fullmatch(r'(?:ior|rior|erior|terior)(?:s|e|es|um)?', s):
        strength = 8.8 if 'erior' in s else 5.5
        if previous.strip().endswith(
                ('inter', 'infer', 'super', 'poster', 'anter', 'citer')):
            strength = 9.0
        if text.isupper():
            strength *= 1.3
        return strength
    if re.fullmatch(r'i?yor', s):
        return 8.0 if s.startswith('i') else 6.5
    if s.startswith('or') and previous.endswith(('i', 'y', 'ie')):
        if s == 'ori':
            return 2.4
        if not re.fullmatch(r'or|ors|ord|orum', s):
            return 1.5
        if previous.endswith(('uy', 'iy', 'ıy')):
            return 10.5
        if previous.endswith('y'):
            strength = 5.2 if previous.strip() == 'y' else 3.0
        elif previous.strip() == 'pri':
            strength = 2.0
        else:
            strength = 3.8
        if text.isupper():
            strength *= 1.5
        return strength
    # French accented comparative fragments, then a feminine/plural ending.
    if re.fullmatch(r'erieur|ieurs?', s) or text.lower() == 'érie':
        return 3.0
    if previous.endswith('erie') and re.fullmatch(r'ures?|urement', s):
        return 7.0
    if previous.strip() in COMPARATIVES:
        if s in ('i', 's', 'es'):
            return 0.4 * COMPARATIVES[previous.strip()]
        if s in ('ity', 'ite', 'itat', 'ita', 'idad', 'idade'):
            return 0.55 * COMPARATIVES[previous.strip()]
    # The same vowel transition occurs in Cyrillic and other Latin endings.
    if s == 'ор' and previous.endswith(('и', 'й')):
        return 5.5
    if previous.endswith('ie') and s in ('u', 'uw'):
        return (3.8 if s == 'u' else 2.7)
    if previous.endswith('io') and s == 'are':
        return 6.8
    if previous.endswith('er') and s == 'io':
        return 1.9
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    text = prefix.token_strings[-1]
    value = response(previous, text)
    return (document, plain(text)), value

programs.haiku:
"""Words of position and rank from Latin-style '-ior' comparatives (superior, inferior,
anterior, posterior, interior, exterior, senior, junior, prior), their French and Italian
cousins ('-rieur', '-riore'), and the Turkish present-continuous ending '-iyor'.

The component fires on the token that completes such a word, with a size that depends on
the word. Everywhere else it predicts 0. A word is matched by the letters written so far
in the current document (the trailing letters of the text up to this token)."""
READS = ()

# typical activation of the common words, from training windows
WORD_VALUE = {
    "posterior": 10.0, "inferior": 10.0, "superior": 7.5, "anterior": 6.5,
    "ulterior": 6.0, "interior": 5.0, "exterior": 4.3, "senior": 2.9,
    "junior": 2.9, "prior": 1.2, "subordinate": 3.0, "superintendent": 1.5,
    "tertiary": 1.1, "subsequent": 0.8, "successor": 0.9, "predecessor": 0.8,
}

def trailing_word(prefix):
    """Letters of the word being written, up to and including this token, within its document."""
    word = ""
    t = len(prefix.token_ids) - 1
    doc = prefix.document_ids[t]
    for i in range(t, max(-1, t - 12), -1):
        if prefix.document_ids[i] != doc:
            break
        piece = prefix.token_strings[i]
        j = len(piece)
        while j > 0 and piece[j - 1].isalpha():
            j -= 1
        word = piece[j:] + word
        if j > 0:
            break
    return word.lower()

def step(carry, prefix, upstream):
    w = trailing_word(prefix)
    if w in WORD_VALUE:
        return None, WORD_VALUE[w]
    if "iyor" in w or "uyor" in w:
        return None, 6.5
    if w.endswith(("riore", "rieur", "rieure", "rieurs", "rieures", "iores", "ioare")):
        return None, 5.0
    if w.endswith(("erior", "terior")):
        return None, 4.0
    if w.endswith("rior"):
        return None, 2.5
    if w.endswith("ior") and not w.endswith("vior"):
        return None, 4.3
    return None, 0.0

programs.sol:
"""Approximate a Chinese spatial/temporal-expression detector.

Location suffixes and words for surroundings, surfaces, and particular times
receive negative values. Dictionary glosses extend the same rules to related
words. Calendar units depend on the preceding numeral; clock hours differ
from the suffix meaning "when". Recent kana indicates Japanese text,
where most of these signals are weakened. Other tokens are left near zero.
This coarse approximation omits most variation within each word class.
"""
from functools import lru_cache
import regex as re
import cedict
from typing import NamedTuple
from opencc import OpenCC

READS = ()
_CONVERTER = OpenCC('t2s')
HAN_END = re.compile(r'\p{Script=Han}$')
NUMBER_END = re.compile(r'[0-9０-９一二三四五六七八九十百千几幾两]$')

SPATIAL = re.compile(
    r'\b(inside|outside|interior|underneath|beneath|surroundings|environs|'
    r'periphery|vicinity|nearby|roof|upstream|downstream|riverside|'
    r'shore|coast|seaside|seashore|beach|roadside|surface|topmost|bottom|'
    r'edge|lateral|downtown|outskirts|outdoors|countryside|above|below|'
    r'ahead|behind|front|back|rear|side|central|middle|center|scene)\b|'
    r'\b(in front of|in the midst|upper reaches|upper part|lower part|'
    r'left side|right side|at the side|at the back|at the end)\b'
)
TEMPORAL = re.compile(
    r'\b(today|tomorrow|yesterday|tonight|morning|afternoon|evening|'
    r'midnight|daytime|weekend|nowadays|future|recently|winter|summer|'
    r'autumn|springtime)\b|'
    r'\b(at that time|at the time|last night|last week|next week|'
    r'this week|last month|next month|that day|next day|since then)\b'
)
WEAK_TIME = set('同时 的同时 目前 现在 今年 去年 明年 当年'.split())
SPATIAL_EXTENTS = set('附近 四周 周围 深处 边缘'.split())


class Signal(NamedTuple):
    strength: float
    needs_left_context: bool = False
    japanese_scale: float = 0.15


# Standalone localizers: preceding Han text/numerals favor the suffix reading.
LOCALIZERS = (
    ('前后', -1.27, True),       # before / after
    ('上下', -0.69, True),       # on / under
    ('中', -0.33, False),        # middle / among
    ('里内外', -0.89, True),     # inside / outside
    ('旁间际畔郊', -2.23, True), # beside / between / outskirts
    ('边处围', -1.17, True),     # edge / place / surroundings
    ('头尾顶底', -0.93, True),   # ends / top / bottom
    ('部侧角口区层面', -0.48, False),  # section / side / surface
    ('期末季', -1.10, False),    # period / end / season
)
# (ordinary reading, reading after a numeral)
UNITS = {'年': (-0.28, -1.74), '月': (-0.31, -1.07),
         '日': (-0.85, -0.84), '时': (-0.92, 1.06)}


@lru_cache(maxsize=32768)
def simplified(token):
    return _CONVERTER.convert(token)


@lru_cache(maxsize=32768)
def word_signal(s):
    if len(s) == 1:
        for characters, strength, attached in LOCALIZERS:
            if s in characters:
                return Signal(strength, attached)
    if s in {'左', '右', '左右', '上下', '以上', '以下', '以内',
             '以外', '其中', '此外', '然后', '另外', '提前', '当前'}:
        return Signal(-0.1)
    if re.fullmatch(r'[春夏秋冬][天季]', s):
        return Signal(-1.17)
    if s in WEAK_TIME:
        return Signal(-0.28)
    if s in SPATIAL_EXTENTS:
        return Signal(-3.4)
    if re.search(r'[年月](底|末|初|份)$', s):
        return Signal(-2.63, japanese_scale=0.7)
    if ('时候' in s or s.endswith(('期间', '时期', '最后'))
            or s in {'最后一', '之际'}):
        return Signal(-1.62)
    if s.endswith(('之前', '之后', '以前', '以后', '过程中')):
        return Signal(-0.83)
    if len(s) > 1 and s.endswith(('上的', '里的', '中的', '年的')):
        return Signal(-0.4)

    # Ignore usage notes and examples; inspect the first ordinary gloss.
    glosses = [g for g in cedict.glosses(s) if not g.startswith(
        ('surname ', 'variant ', 'old variant ', 'CL:', 'used in ', 'abbr.', '(')
    )]
    gloss = re.sub(r'\([^)]*\)', '', glosses[0]).lower() if glosses else ''
    body_region = s.endswith('部') and re.search(
        r'\b(face|head|abdomen|chest|body|leg|arm)\b', gloss
    )
    if SPATIAL.search(gloss) or body_region:
        return Signal(-1.12 if len(s) > 1 else 0.0)
    if TEMPORAL.search(gloss) or any(
        g in {'period', 'season', 'century', 'era'} for g in glosses[:1]
    ):
        return Signal(-1.17 if len(s) > 1 else -0.1)
    if (re.fullmatch(r'\p{Script=Han}{2,5}', s)
            and s.endswith(('里', '中', '内', '外', '前', '后', '上', '下'))
            and not gloss.startswith('to ')):
        return Signal(-0.54)
    if not gloss and len(s) > 1 and s.endswith(('边', '旁', '际', '顶', '底')):
        return Signal(-1.12)
    return Signal(0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else b''
    text = before.decode('utf-8', errors='replace')
    raw = prefix.token_bytes[-1]
    token = prefix.token_strings[-1]
    if '\ufffd' in token:  # Recover a character completed by continuation bytes.
        joined = (before + raw).decode('utf-8', 'replace')
        completed = joined[len(text.rstrip('\ufffd')):]
        if completed and '\ufffd' not in completed:
            token = completed
    s = simplified(token)
    number = bool(NUMBER_END.search(text))
    if s in UNITS:
        value = UNITS[s][number]
        scale = 0.4 if number and s in '年月' else 0.15
        if (s in '年月' and not number) or (s == '时' and number):
            scale = 1.0
    else:
        signal = word_signal(s)
        value, scale = signal.strength, signal.japanese_scale
        if signal.needs_left_context and not (number or HAN_END.search(text)):
            value = -0.39
    if re.search(r'\p{Script=Hiragana}|\p{Script=Katakana}', text):
        value *= scale
    return (doc, (before + raw)[-64:]), value

"""Approximate a numerical-format signal, chiefly years and decimal points.

A leading 19 or 20 is negative, more strongly after date language or citation
markers and less strongly in numerical/code contexts. Finishing a four-digit
year is positive. Decimal/version dots are negative; list-number dots are not.
Numerical estimates are shrunk toward zero to limit false positives.
Two document-initial heading forms have separate, reproducible responses.
All context is past text, capped at 160 characters, reset at document changes.
"""
import calendar
import re

READS = ()
MONTHS = {x.lower() for x in calendar.month_name if x}
SHORT_MONTHS = {x.lower() for x in calendar.month_abbr if x} - MONTHS
DATE_PREPOSITIONS = set(
    'in since during until before after by from between through'.split()
)
YEAR_WORDS = set(
    'born died birth death year years annual dated copyright founded '
    'established fy'.split()
)
MATH = re.compile(
    r'[=+*^]|\b(?:step|equation|divided|multiply|integer|modulo|power|'
    r'let|less than|greater than)\b', re.I
)
CODE = re.compile(
    r'__|=>|\b(?:const|var|int|return|import|default|error)\b|[{}]', re.I
)
CITATION = re.compile(r'\bet\s+al\b[^\w]*$|\\cite\w*\{[^}]*$', re.I)


def year_prefix(before, digits, decimal):
    """Size of the negative response to a possible modern-year prefix."""
    recent = before[-80:]
    if re.search(r'copyright(?:\s*\(c\))?[^A-Za-z]{0,12}$', recent, re.I):
        return -3.5
    if CITATION.search(recent):
        return -3.8
    words = re.findall(r'[A-Za-z]+', recent.lower())
    last = words[-1] if words else ''
    value = -1.7 - 0.33 * (digits == '19')
    value -= 1.02 * (last in DATE_PREPOSITIONS)
    value -= 0.76 * (last == 'the')
    value -= 0.86 * (last in MONTHS)
    value -= 0.19 * (last in SHORT_MONTHS)
    value -= 1.47 * (last in YEAR_WORDS)
    value -= 0.0057 * sum(c.isalpha() for c in recent)
    value += 0.24 * min(3, sum(c.isdigit() for c in recent) / 10)
    value += 0.48 * bool(CODE.search(recent))
    value += 0.82 * bool(MATH.search(recent))
    value += 0.3 * (not before or before.endswith(('\n', '\t')))
    value += 0.52 * bool(re.search(r'\d[^\w\n]{0,4}$', recent))
    value += 0.64 * recent.rstrip().endswith('-')
    value += 0.51 * recent.rstrip().endswith(':')
    value += 1.21 * bool(re.search(r'[$€£¥]\s*$', recent))
    value += 0.49 * decimal
    return max(-6.0, min(0.0, value))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', '', False)
    _, text, number, before, decimal = carry
    token = prefix.token_strings[-1]
    value = 0.0
    if token.isascii() and token.isdigit():
        if not number:
            before = text
        number += token
        n = len(number)
        if n == 2 and number in ('19', '20'):
            value = year_prefix(before, number, decimal)
        elif n == 2 and number == '18':
            value = -0.25
        elif n == 4 and 1800 <= int(number) < 2100:
            year = int(number)
            if year < 1900:
                value = 0.45
            elif year < 2000:
                value = min(1.25, 0.45 + (year - 1900) / 100)
            else:
                value = 1.2 if year < 2020 else 0.65
            if year == 2000:
                value = 0.7
            if number == '2020':
                value = 1.3
            if decimal:
                value *= 0.2
    else:
        if token == '.' and number:
            line = text.rsplit('\n', 1)[-1]
            is_list = re.fullmatch(r'\s*(?:#+\s*)?\d+', line)
            if len(number) < 4:
                value = -0.75 if len(number) == 1 else -0.6
                if len(number) == 3:
                    value = -0.45
                if number == '0':
                    value = -1.17
                elif number == '1':
                    value = -0.9
                if is_list:
                    value *= 0.08
                if decimal:
                    value = -0.05
        decimal = token == '.' and bool(number)
        number = ''
    # Numerical estimates are uncertain; do not shrink the heading exceptions.
    value *= 0.8
    if not text and token == 'Title':
        value = 1.15
    elif text == 'Title' and token == ':':
        value = -11.79
    elif not text and token == '##':
        value = -1.17
    text = (text + token)[-160:]
    return (doc, text, number, before, decimal), float(value)

"""Lexical responses to Chinese comparisons and milk/breast words.

Standalone Chinese resemblance words receive a strong positive value; merged
comparison phrases are weaker. Milk/breast characters are another positive
family. English 'like' and long runs of middle dots have negative responses.
This leaves unrelated words and most small contextual fluctuations at zero.
"""
READS = ()

# 'Seems like' / 'unlike'; 'just like'; and simile/example phrases.
STRONG_COMPARISONS = {'像是', '不像'}
EMPHATIC_COMPARISONS = {'就像', '就像是'}
SIMILE_PHRASES = {'如同', '诸如'}
OTHER_COMPARISONS = {
    '如', '似', '仿佛', '宛如', '犹如', '好像', '就好像',
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1]
    if word == '像':  # like / image
        value = 6.8
    elif word in STRONG_COMPARISONS:
        value = 5.8
    elif word in EMPHATIC_COMPARISONS:
        value = 2.3
    elif word in SIMILE_PHRASES:
        value = 1.7
    elif word in OTHER_COMPARISONS:
        value = 0.7
    elif word == '乳':  # milk / breast
        value = 4.8
    elif word == '奶':  # milk; also colloquial breast
        value = 3.0
    elif word.strip().lower() == 'like':
        value = -0.2
    elif (word == '··' and prefix.position > 0
          and prefix.document_ids[-1] == prefix.document_ids[-2]
          and prefix.token_strings[-2] == '··'):
        value = -0.62
    else:
        value = 0.0
    return None, value

