"""Activation of layers.1.mlp.down_proj:1276, predicted from the current token alone.

The component is a lexical "resemblance" feature: it fires on the Chinese word 像
("to be like / to resemble", also "a statue"), on the phrases built on it, and on
the comparison words 如 / 如同 / 诸如 ("as, like"), and on the breast words 乳 / 奶.
Everywhere else it is near zero, except a small negative response to the repeated
dot token "··" and to English "like".
"""

READS = ()

# 像 itself, the strongest trigger.
RESEMBLE = {"像": 7.0}

# Phrases built on 像 and other comparison words ("is like", "as if", "such as").
COMPARE = {
    "像是": 4.0, "像个": 4.0, "不像": 4.0, "更像是": 3.0,
    "就像": 2.5, "就像是": 2.5, "如同": 1.5, "诸如": 2.0, "如": 0.6,
}

# Breast words; 乳 is the strong one, 奶 ("milk, breast") weaker.
BREAST = {"乳": 4.75, "奶": 3.0}

# Small negative responses: the dot-run token and English "like".
NEGATIVE = {"··": -0.6, " like": -0.2}

VALUES = {**RESEMBLE, **COMPARE, **BREAST, **NEGATIVE}


def step(carry, prefix, upstream):
    """Stateless: look up the newest token's typical activation, 0 for other tokens."""
    return carry, float(VALUES.get(prefix.token_strings[-1], 0.0))

