"""Predict literal waiting/hesitation words and field-opening quotes.

'Wait' and 'hmm' forms get strong positives; 'Oh', 'Ah', and 'Uh'
get weaker ones. A space-prefixed quote responds to local JSON-field
syntax or include/import text. Other tokens use a near-zero baseline,
except for a coarse shape-based offset at document starts. This only
approximates the highly token-specific startup values.
The state resets at document boundaries and retains 160 recent characters.
"""
import re

READS = ()


def opening_quote(recent):
    last = recent.rstrip()
    if last.endswith(','):
        multiline = '\n' in recent[len(last):]
        # A completed string-valued field suggests another key follows.
        if re.search(r'"[^"\n]*"\s*:\s*"[^"\n]*",\s*$', recent):
            return 0.40 if multiline else 0.59
        if re.search(r'[}\]]\s*,\s*$', recent):
            return 0.36 if multiline else 0.26
        if re.search(r'"\s*,\s*$', recent):
            return 0.08
    if last.endswith('{'):
        return 0.37
    if last.endswith('include'):
        return 0.27
    if last.endswith('import'):
        return 0.40
    return -0.003


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, recent = 0, ''
    else:
        position, recent = carry[1], carry[2]
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    spaced = token.startswith(' ')
    value = -0.003
    if lower == 'wait':
        value = 0.80 if spaced and word.istitle() else 0.70
    elif lower in ('waited', 'waiting', 'waits'):
        value = 0.40
    elif re.fullmatch('hm{2,}', lower):
        value = 0.59 if spaced else 0.50
    elif word in ('Oh', 'Ah', 'Uh'):
        value = 0.12 if spaced else 0.20
    elif token == ' "':
        value = opening_quote(recent)
    elif position == 0 and not token.startswith('<|'):
        value = -0.24
        if token.isspace():
            value = 0.22 if '\n' in token or token == ' ' else -0.55
        elif word.isdigit():
            value = -0.09
        elif spaced and word.islower():
            value = -0.12
    return (doc, position + 1, (recent + token)[-160:]), value

"""Approximate a short-fragment continuation signal.

Boost short, unspaced letter pieces, especially the second piece after a
one-letter start. UTF-8 continuation bytes, combining marks, small kana,
and Greek letter runs receive separate boosts. Ideographs and Korean
syllables skip the alphabetic-fragment rule. Other tokens stay near zero,
with a negative correction at the first position of each document.
These are surface-form rules, not recognition of complete words.
"""
import unicodedata

READS = ()


def script(text):
    """The Unicode script of the first letter, if there is one."""
    for ch in text:
        if ch.isalpha():
            name = unicodedata.name(ch, '')
            for kind in ('LATIN', 'CYRILLIC', 'GREEK', 'HIRAGANA',
                         'KATAKANA', 'HANGUL', 'CJK', 'ARABIC'):
                if kind in name:
                    return kind
            return 'OTHER'
    return ''


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    if carry is None or carry[0] != doc:
        previous, pieces, word_length, position = '', 0, 0, 0
    else:
        _, previous, pieces, word_length, position = carry

    clean = text.strip()
    kind = script(clean)
    joined = previous[-1:].isalpha() and text[:1].isalpha()
    value = -0.009 - 0.42 * (position == 0)

    # Finishing a character, rather than beginning a new one.
    if raw and 128 <= raw[0] < 192:
        value += 0.60
    if clean and all(unicodedata.category(c).startswith('M') for c in clean):
        value += 0.65
    if (len(text) == 1 and kind in ('HIRAGANA', 'KATAKANA')
            and 'SMALL' in unicodedata.name(text, '')):
        value += 1.08

    # A word-like run is tracked by token pieces and character length.
    if joined and kind not in ('CJK', 'HANGUL'):
        previous_length = len(previous.strip())
        one_letter_start = (
            pieces == 1 and previous_length == 1
            and script(previous) not in ('CJK', 'HANGUL', 'HIRAGANA')
        )
        if one_letter_start:
            if clean.isascii():
                value += 0.42 if len(raw) <= 3 else 0.18
            else:
                value += 0.89 if len(raw) <= 3 else 0.55
        elif len(clean) <= 2:
            if word_length <= 3:
                value += 0.35
            elif len(clean) == 1:
                value += 0.15
        elif pieces == 1 and previous_length == 2:
            value += 0.10
    if joined and kind == 'GREEK':
        value += 0.20

    if joined:
        pieces += 1
        word_length += len(clean)
    else:
        pieces = int(text[-1:].isalpha())
        word_length = len(clean)
    return (doc, text, pieces, word_length, position + 1), value

