"""layers.1.mlp.down_proj:1278 -- a word-internal fragment detector.

What it does: this component is near zero on most tokens. It turns on at a token that
continues a word the tokenizer has split into pieces, when the previous token starts the
word (carries a leading space and letters). It is strongest when that continuation is a
single letter of a non-Latin alphabet (Greek, Cyrillic, Arabic, Katakana, ...), e.g. the
second piece of a rare word spelled out in characters. A single ASCII letter in the same
position is moderate, and a multi-letter non-Latin piece is weaker. A stray half-character
byte (U+FFFD, which decodes alone to the replacement character) is also moderately positive.
Everything else, including tokens starting with a space, punctuation, digits, and the first
token of a document, is predicted as 0.

Why: the component's activation is a sparse, graded signal on mid-word letter pieces,
mostly in multilingual text, where the next piece of an unfamiliar word is still open.
Values are fitted by group means on a training sample; scale 1 was best.
"""
import unicodedata

READS = ()


def _is_letter(ch):
    return unicodedata.category(ch).startswith("L")


def _has_letter(s):
    return any(_is_letter(c) for c in s)


def _nonlatin(s):
    # letters from Greek (U+0370) upward: Greek, Cyrillic, Arabic, Kana, Hangul, CJK, ...
    return any(_is_letter(c) and ord(c) >= 0x370 for c in s)


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    if "�" in cur:
        return None, 0.4  # a partial UTF-8 byte
    if prefix.position == 0 or cur[:1] == " " or not _has_letter(cur):
        return None, 0.0  # word starts, punctuation, digits, and document starts
    if prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0  # the previous token belongs to another document
    prev = prefix.token_strings[-2]
    if not _has_letter(prev) or prev[:1] != " ":
        return None, 0.0  # the word must start at the previous token
    single = len(cur) == 1
    if single and _nonlatin(cur):
        return None, 0.75
    if single:
        return None, 0.45
    if _nonlatin(cur):
        return None, 0.3
    return None, 0.05

programs.sol:
"""Approximate selected local preposition and source constructions.

Relative imports and 'from one' receive negative values. Adverbial source
phrases ('from across', 'from before') receive positive values, unlike most
ordinary noun phrases. Smaller rules cover approximate amounts, clauses,
and a few multilingual temporal/discourse phrases. Values are estimates,
not an exhaustive grammar. Remember two tokens; reset at document changes.
"""
READS: tuple[str, ...] = ()

SOURCE_ADVERBS = set('above below before earlier inside outside within '
                     'between over under out off underneath'.split())
APPROXIMATORS = set('about around almost nearly under'.split())


def response(previous, token):
    old = previous.strip().lower()
    word = token.strip().lower()
    if old == 'from':
        # Quoted relative module paths; Python also permits bare leading dots.
        if './' in token:
            depth = token.count('../')
            return -8.6 - min(depth, 3) * 1.0
        if token[:1].isspace() and word and set(word) == {'.'}:
            return -4.6 if len(word) == 1 else -9.0
        if word.startswith(('"@', "'@")):
            return -4.4  # scoped/aliased module path
        if word in {'\"', "'"}:
            return -1.0
        if word == 'one':
            return -5.5
        if word in {'across', 'around', 'beyond'}:
            return 6.0
        if word in SOURCE_ADVERBS:
            return 3.4
        if word == 'now':
            return -3.3
        if word in {'there', 'home'}:
            return -0.8
        if word == 'where':
            return -2.3
        if word in {'about', 'roughly', 'least'}:
            return 2.0
        if word in {'time', 'previous', 'last'}:
            return 1.2
        if word in {'largest', 'smallest'}:
            return 3.5
        if word == 'typing':
            return -5.0  # Python's type-annotation imports
        if word == '__':
            return 4.4  # start of __future__ imports
    if old == 'require' and './' in token:
        return -8.0 if '../' in token else -5.5
    if old == 'use' and word == 'crate':
        return -8.8  # Rust's local-crate imports
    if old == 'for':
        if token.strip() == 'I':
            return 1.2
        # Explanatory clauses and duration/amount modifiers.
        if word in {'he', 'she', 'they', 'if'}:
            return 2.8
        if word in {'as', 'when', 'later', 'over', 'longer'}:
            return 2.1
        if word in APPROXIMATORS or word in {'use', 'help', 'too'}:
            return 1.0
        if word in {'it', 'no', 'up', 'ever'}:
            return 0.7
        if word == 'you':
            return 0.5
        if word == 'the':
            return -0.12
    if old == 'at':
        if word in {'about', 'around', 'over'}:
            return 1.2
        if word == 'least':
            return 0.28
    if old == 'until' and word == 'after':
        return 5.4
    if old == 'since' and word == 'before':
        return 5.4
    if old in {'of', 'to', 'in', 'with', 'by', 'between', 'within'}:
        if word in {'about', 'around', 'over', 'under'}:
            return 0.65
    if old in {'because', 'on', 'since'} and word == 'if':
        return 0.55
    if old == 'since' and word == 'otherwise':
        return 3.3
    if old == 'than' and word == 'before':
        return 1.1
    if old == 'well' and word == 'over':
        return 0.65
    return -0.004


# Small cross-language versions of temporal/discourse constructions.
def other_languages(previous, word):
    if previous in {'从', '從'}:
        if word == '现在':
            return -3.6
        if word in {'前', '远', '不', '开始'}:
            return 4.3
    if previous == 'de':
        if word == 'plus':
            return 2.4
        if word == 'même':
            return 3.5
    if (previous, word) in {('von', 'über'), ('từ', 'trước'),
                            ('trong', 'khi')}:
        return 4.5
    if (previous, word) in {('da', 'sempre'), ('para', 'sempre'),
                            ('depuis', 'toujours')}:
        return 3.7
    return None


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before = '', ''
    else:
        previous, before = carry[1:]
    old, word = previous.strip().lower(), token.strip().lower()
    value = response(previous, token)
    if before.strip().lower() == 'from':
        if old == 'the' and word in {'time', 'moment'}:
            value = 2.6
        elif old == 'all' and word == 'over':
            value = 3.7
        elif old.endswith(('"', "'")) and word.startswith('./'):
            value = -5.2
        elif old.endswith('@') and word in {
            'shared', 'utils', 'api', 'context'
        }:
            value = -4.8
        elif old == '__' and word == 'future':
            value = 1.6
    multilingual = other_languages(old, word)
    if multilingual is not None:
        value = multilingual
    return (doc, token, previous), value
